24: /**
25:  * Currently available join strategies and corresponding join hint names.
26:  *
27:  * <p>The process for handling join hints is as follows:
28:  *
29:  * <ol>
30:  *   <li>Resolve join hint propagation:
31:  *       <ol>
32:  *         <li>The join hints are resolved using Calcite's functionality to propagate them from the
33:  *             sink to the source and within sub-queries
34:  *         <li>Capitalize join hints: All join hints are capitalized to ensure consistency, as they
35:  *             are expected to be in uppercase.
36:  *         <li>Clear incorrectly propagated join hints: Any join hints that have been mistakenly
37:  *             propagated into the query block are cleared.
38:  *         <li>Clear join hints from unmatched nodes: Join hints attached to unmatched nodes, such
39:  *             as {@link org.apache.calcite.rel.core.Project}, are also cleared.
40:  *       </ol>
41:  *   <li>Validate and modify join hints: The join hints are validated, and the table names in the
42:  *       hints are replaced with LEFT or RIGHT to indicate the join input ordinal.
43:  *   <li>Clear query block aliases: The query block aliases are cleared from the sink to the source.
44:  *   <li>Consume join hints in applicable rules: Finally, the join hints are consumed in specific
45:  *       rules where they are relevant.
46:  * </ol>
47:  */
48: public enum JoinStrategy {
49:     /**
50:      * Instructs the optimizer to use broadcast hash join strategy. If both sides are specified in
51:      * this hint, the side that is first written will be broadcast.
52:      */
53:     BROADCAST("BROADCAST"),
54: 
55:     /**
56:      * Instructs the optimizer to use shuffle hash join strategy. If both sides are specified in
57:      * this hint, the side that is first written will be treated as the build side.
58:      */
59:     SHUFFLE_HASH("SHUFFLE_HASH"),
60: 
61:     /**
62:      * Instructs the optimizer to use shuffle sort merge join strategy. As long as one of the side
63:      * is specified in this hint, it will be tried.
64:      */
65:     SHUFFLE_MERGE("SHUFFLE_MERGE"),
66: 
67:     /**
68:      * Instructs the optimizer to use nest loop join strategy. If both sides are specified in this
69:      * hint, the side that is first written will be treated as the build side.
70:      */
71:     NEST_LOOP("NEST_LOOP"),
72: 
73:     /** Instructs the optimizer to use lookup join strategy. Only accept key-value hint options. */
74:     LOOKUP("LOOKUP");
75: 
76:     private final String joinHintName;
77: 
78:     JoinStrategy(String joinHintName) {
79:         this.joinHintName = joinHintName;
80:     }
81: 
82:     // ~ option name for join hint
83:     public static final String LEFT_INPUT = "LEFT";
84:     public static final String RIGHT_INPUT = "RIGHT";
85: 
86:     public static boolean isJoinStrategy(String hintName) {
87:         try {
88:             JoinStrategy.valueOf(hintName.toUpperCase(Locale.ROOT));
89:             return true;
90:         } catch (Exception e) {
91:             return false;
92:         }
93:     }
94: 
95:     public String getJoinHintName() {
96:         return joinHintName;
97:     }
98: 
99:     public static boolean validOptions(String hintName, List<String> options) {
100:         if (!isJoinStrategy(hintName)) {
101:             return false;
102:         }
103: 
104:         JoinStrategy strategy = JoinStrategy.valueOf(hintName);
105:         switch (strategy) {
106:             case SHUFFLE_HASH:
107:             case SHUFFLE_MERGE:
108:             case BROADCAST:
109:             case NEST_LOOP:
110:                 return options.size() > 0;
111:             case LOOKUP:
112:                 return null == options || options.size() == 0;
113:         }
114:         return false;
115:     }
116: 
117:     public static boolean isLookupHint(String hintName) {
118:         String formalizedHintName = hintName.toUpperCase(Locale.ROOT);
119:         return isJoinStrategy(formalizedHintName)
120:                 && JoinStrategy.valueOf(formalizedHintName) == LOOKUP;
121:     }
122: }
