381:             throw new FlinkRuntimeException("Failed to get keys from RocksDB state backend.", ex);
382:         }
383: 
384:         RocksIteratorWrapper iterator =
385:                 RocksDBOperationUtils.getRocksIterator(
386:                         db, columnInfo.columnFamilyHandle, readOptions);
387:         iterator.seekToFirst();
388: 
389:         final RocksStateKeysIterator<K> iteratorWrapper =
390:                 new RocksStateKeysIterator<>(
391:                         iterator,
392:                         state,
393:                         getKeySerializer(),
394:                         keyGroupPrefixBytes,
395:                         ambiguousKeyPossible,
396:                         nameSpaceBytes);
397: 
398:         Stream<K> targetStream =
399:                 StreamSupport.stream(
400:                         Spliterators.spliteratorUnknownSize(iteratorWrapper, Spliterator.ORDERED),
401:                         false);
402:         return targetStream.onClose(iteratorWrapper::close);
403:     }
