405:     @SuppressWarnings("unchecked")
406:     @Override
407:     public <N> Stream<K> getKeys(List<String> states, N namespace) {
408:         final List<Boolean> ambiguousKeyPossibles = new ArrayList<>();
409:         final List<RocksIteratorWrapper> iterators = new ArrayList<>();
410:         byte[] namespaceBytes = null;
411: 
412:         for (String state : states) {
413:             RocksDbKvStateInfo columnInfo = kvStateInformation.get(state);
414:             if (columnInfo == null
415:                     || !(columnInfo.metaInfo instanceof RegisteredKeyValueStateBackendMetaInfo)) {
416:                 continue;
417:             }
418: 
419:             RegisteredKeyValueStateBackendMetaInfo<N, ?> registeredKeyValueStateBackendMetaInfo =
420:                     (RegisteredKeyValueStateBackendMetaInfo<N, ?>) columnInfo.metaInfo;
421: 
422:             final TypeSerializer<N> namespaceSerializer =
423:                     registeredKeyValueStateBackendMetaInfo.getNamespaceSerializer();
424:             final DataOutputSerializer namespaceOutputView = new DataOutputSerializer(8);
425:             boolean ambiguousKeyPossible =
426:                     CompositeKeySerializationUtils.isAmbiguousKeyPossible(
427:                             getKeySerializer(), namespaceSerializer);
428:             ambiguousKeyPossibles.add(ambiguousKeyPossible);
429:             try {
430:                 CompositeKeySerializationUtils.writeNameSpace(
431:                         namespace, namespaceSerializer, namespaceOutputView, ambiguousKeyPossible);
432:                 final byte[] stateNamespaceBytes = namespaceOutputView.getCopyOfBuffer();
433:                 if (namespaceBytes == null) {
434:                     namespaceBytes = stateNamespaceBytes;
435:                 } else {
436:                     if (!Arrays.equals(namespaceBytes, stateNamespaceBytes)) {
437:                         throw new FlinkRuntimeException(
438:                                 "Key namespaces are different for states ["
439:                                         + String.join(",", states)
440:                                         + "]");
441:                     }
442:                 }
443:             } catch (IOException ex) {
444:                 throw new FlinkRuntimeException(
445:                         "Failed to get keys from RocksDB state backend.", ex);
446:             }
447: 
448:             RocksIteratorWrapper iterator =
449:                     RocksDBOperationUtils.getRocksIterator(
450:                             db, columnInfo.columnFamilyHandle, readOptions);
451:             iterator.seekToFirst();
452:             iterators.add(iterator);
453:         }
454: 
455:         Preconditions.checkNotNull(namespaceBytes, "Namespace must exist");
456:         final RocksMultiStateKeysIterator<K> iteratorWrapper =
457:                 new RocksMultiStateKeysIterator<>(
458:                         iterators,
459:                         states,
460:                         getKeySerializer(),
461:                         keyGroupPrefixBytes,
462:                         ambiguousKeyPossibles,
463:                         namespaceBytes);
464: 
465:         Stream<K> targetStream =
466:                 StreamSupport.stream(
467:                         Spliterators.spliteratorUnknownSize(iteratorWrapper, Spliterator.ORDERED),
468:                         false);
469:         return targetStream.onClose(iteratorWrapper::close);
470:     }
