984:     @SuppressWarnings("unchecked")
985:     private static <UK> boolean checkMapStateKeySchemaCompatibility(
986:             MapSerializerSnapshot<?, ?> mapStateSerializerSnapshot,
987:             MapSerializer<?, ?> newMapStateSerializer) {
988:         TypeSerializerSnapshot<UK> previousKeySerializerSnapshot =
989:                 (TypeSerializerSnapshot<UK>) mapStateSerializerSnapshot.getKeySerializerSnapshot();
990:         TypeSerializer<UK> newUserKeySerializer =
991:                 (TypeSerializer<UK>) newMapStateSerializer.getKeySerializer();
992: 
993:         TypeSerializerSchemaCompatibility<UK> keyCompatibility =
994:                 newUserKeySerializer
995:                         .snapshotConfiguration()
996:                         .resolveSchemaCompatibility(previousKeySerializerSnapshot);
997:         return keyCompatibility.isCompatibleAsIs();
998:     }
