268:         ForStNativeMetricMonitor nativeMetricMonitor = null;
269:         CloseableRegistry cancelRegistryForBackend = new CloseableRegistry();
270:         LinkedHashMap<String, ForStOperationUtils.ForStKvStateInfo> kvStateInformation =
271:                 new LinkedHashMap<>();
272:         LinkedHashMap<String, HeapPriorityQueueSnapshotRestoreWrapper<?>> registeredPQStates =
273:                 new LinkedHashMap<>();
274:         RocksDB db = null;
275:         ForStRestoreOperation restoreOperation = null;
276:         CompletableFuture<Void> asyncCompactAfterRestoreFuture = null;
277: 
278:         ForStDBTtlCompactFiltersManager ttlCompactFiltersManager =
279:                 new ForStDBTtlCompactFiltersManager(
280:                         ttlTimeProvider,
281:                         optionsContainer.getQueryTimeAfterNumEntries(),
282:                         optionsContainer.getPeriodicCompactionTime());
283: 
284:         ForStSnapshotStrategyBase<K, ?> checkpointStrategy = null;
285: 
286:         ResourceGuard forStResourceGuard = new ResourceGuard();
287:         PriorityQueueSetFactory priorityQueueFactory;
288:         SerializedCompositeKeyBuilder<K> sharedRocksKeyBuilder;
289:         // Number of bytes required to prefix the key groups.
290:         int keyGroupPrefixBytes =
291:                 CompositeKeySerializationUtils.computeRequiredBytesInKeyGroupPrefix(
292:                         numberOfKeyGroups);
293: 
294:         try {
295:             // Current thread (task thread) must be a Flink thread to enable proper cache
296:             // management.
297:             setFlinkThread();
298:             // Variables for snapshot strategy when incremental checkpoint is enabled
299:             UUID backendUID = UUID.randomUUID();
300:             SortedMap<Long, Collection<HandleAndLocalPath>> materializedSstFiles = new TreeMap<>();
301:             long lastCompletedCheckpointId = -1L;
302:             optionsContainer.prepareDirectories();
303:             restoreOperation =
304:                     getForStDBRestoreOperation(
305:                             keyGroupPrefixBytes,
306:                             kvStateInformation,
307:                             registeredPQStates,
308:                             ttlCompactFiltersManager);
309:             ForStRestoreResult restoreResult = restoreOperation.restore();
310:             db = restoreResult.getDb();
311:             defaultColumnFamilyHandle = restoreResult.getDefaultColumnFamilyHandle();
312:             nativeMetricMonitor = restoreResult.getNativeMetricMonitor();
313: 
314:             writeBatchWrapper =
315:                     new ForStDBWriteBatchWrapper(
316:                             db, optionsContainer.getWriteOptions(), writeBatchSize);
317: 
318:             // it is important that we only create the key builder after the restore, and not
319:             // before;
320:             // restore operations may reconfigure the key serializer, so accessing the key
321:             // serializer
322:             // only now we can be certain that the key serializer used in the builder is final.
323:             sharedRocksKeyBuilder =
324:                     new SerializedCompositeKeyBuilder<>(
325:                             keySerializerProvider.currentSchemaSerializer(),
326:                             keyGroupPrefixBytes,
327:                             32);
328:             // init snapshot strategy after db is assured to be initialized
329:             checkpointStrategy =
330:                     initializeSnapshotStrategy(
331:                             db,
332:                             forStResourceGuard,
333:                             keySerializerProvider.currentSchemaSerializer(),
334:                             kvStateInformation,
335:                             keyGroupRange,
336:                             keyGroupPrefixBytes,
337:                             backendUID,
338:                             materializedSstFiles,
339:                             lastCompletedCheckpointId);
340: 
341:             // init priority queue factory
342:             priorityQueueFactory =
343:                     initPriorityQueueFactory(
344:                             keyGroupPrefixBytes,
345:                             kvStateInformation,
346:                             db,
347:                             writeBatchWrapper,
348:                             nativeMetricMonitor);
349:         } catch (Throwable e) {
350:             // Do clean up
351:             List<ColumnFamilyOptions> columnFamilyOptions =
352:                     new ArrayList<>(kvStateInformation.values().size());
353:             IOUtils.closeQuietly(cancelRegistryForBackend);
354:             IOUtils.closeQuietly(writeBatchWrapper);
355:             IOUtils.closeQuietly(forStResourceGuard);
356:             ForStOperationUtils.addColumnFamilyOptionsToCloseLater(
357:                     columnFamilyOptions, defaultColumnFamilyHandle);
358:             IOUtils.closeQuietly(defaultColumnFamilyHandle);
359:             IOUtils.closeQuietly(nativeMetricMonitor);
360:             for (ForStOperationUtils.ForStKvStateInfo kvStateInfo : kvStateInformation.values()) {
361:                 ForStOperationUtils.addColumnFamilyOptionsToCloseLater(
362:                         columnFamilyOptions, kvStateInfo.columnFamilyHandle);
363:                 IOUtils.closeQuietly(kvStateInfo.columnFamilyHandle);
364:             }
365:             IOUtils.closeQuietly(db);
366:             // it's possible that db has been initialized but later restore steps failed
367:             IOUtils.closeQuietly(restoreOperation);
368:             IOUtils.closeAllQuietly(columnFamilyOptions);
369:             IOUtils.closeQuietly(optionsContainer);
370:             ttlCompactFiltersManager.disposeAndClearRegisteredCompactionFactories();
371:             kvStateInformation.clear();
372: 
373:             try {
374:                 FileUtils.deleteDirectory(new File(optionsContainer.getBasePath().getPath()));
375:             } catch (Exception ex) {
376:                 logger.warn(
377:                         "Failed to delete base path for ForSt: " + optionsContainer.getBasePath(),
378:                         ex);
379:             }
380:             // Log and rethrow
381:             if (e instanceof BackendBuildingException) {
382:                 throw (BackendBuildingException) e;
383:             } else {
384:                 String errMsg = "Caught unexpected exception.";
385:                 logger.error(errMsg, e);
386:                 throw new BackendBuildingException(errMsg, e);
387:             }
388:         }
389:         InternalKeyContext<K> keyContext =
390:                 new InternalKeyContextImpl<>(keyGroupRange, numberOfKeyGroups);
391:         logger.info(
392:                 "Finished building ForSt keyed state-backend at {}.",
393:                 optionsContainer.getBasePath());
394:         return new ForStSyncKeyedStateBackend<>(
395:                 this.userCodeClassLoader,
396:                 this.optionsContainer,
397:                 columnFamilyOptionsFactory,
398:                 this.kvStateRegistry,
399:                 this.keySerializerProvider.currentSchemaSerializer(),
400:                 this.executionConfig,
401:                 this.ttlTimeProvider,
402:                 latencyTrackingStateConfig,
403:                 db,
404:                 kvStateInformation,
405:                 registeredPQStates,
406:                 keyGroupPrefixBytes,
407:                 cancelRegistryForBackend,
408:                 this.keyGroupCompressionDecorator,
409:                 forStResourceGuard,
410:                 checkpointStrategy,
411:                 writeBatchWrapper,
412:                 defaultColumnFamilyHandle,
413:                 nativeMetricMonitor,
414:                 sharedRocksKeyBuilder,
415:                 priorityQueueFactory,
416:                 ttlCompactFiltersManager,
417:                 keyContext,
418:                 writeBatchSize,
419:                 asyncCompactAfterRestoreFuture);
420:     }
