446:     private ForStSnapshotStrategyBase<K, ?> initializeSnapshotStrategy(
447:             @Nonnull RocksDB db,
448:             @Nonnull ResourceGuard forstResourceGuard,
449:             @Nonnull TypeSerializer<K> keySerializer,
450:             @Nonnull LinkedHashMap<String, ForStOperationUtils.ForStKvStateInfo> kvStateInformation,
451:             @Nonnull KeyGroupRange keyGroupRange,
452:             @Nonnegative int keyGroupPrefixBytes,
453:             @Nonnull UUID backendUID,
454:             @Nonnull
455:                     SortedMap<Long, Collection<IncrementalKeyedStateHandle.HandleAndLocalPath>>
456:                             uploadedStateHandles,
457:             long lastCompletedCheckpointId)
458:             throws IOException {
459: 
460:         ForStStateDataTransfer stateTransfer =
461:                 new ForStStateDataTransfer(
462:                         ForStStateDataTransfer.DEFAULT_THREAD_NUM,
463:                         optionsContainer.getFileSystem());
464: 
465:         if (enableIncrementalCheckpointing) {
466:             return new ForStIncrementalSnapshotStrategy<>(
467:                     db,
468:                     forstResourceGuard,
469:                     optionsContainer,
470:                     keySerializer,
471:                     kvStateInformation,
472:                     keyGroupRange,
473:                     keyGroupPrefixBytes,
474:                     backendUID,
475:                     uploadedStateHandles,
476:                     stateTransfer,
477:                     lastCompletedCheckpointId);
478:         } else {
479:             return new ForStNativeFullSnapshotStrategy<>(
480:                     db,
481:                     forstResourceGuard,
482:                     optionsContainer,
483:                     keySerializer,
484:                     kvStateInformation,
485:                     keyGroupRange,
486:                     keyGroupPrefixBytes,
487:                     backendUID,
488:                     stateTransfer);
489:         }
490:     }
