492:     private ForStRestoreOperation getForStDBRestoreOperation(
493:             int keyGroupPrefixBytes,
494:             LinkedHashMap<String, ForStOperationUtils.ForStKvStateInfo> kvStateInformation,
495:             LinkedHashMap<String, HeapPriorityQueueSnapshotRestoreWrapper<?>> registeredPQStates,
496:             ForStDBTtlCompactFiltersManager ttlCompactFiltersManager) {
497:         // Currently, ForStDB does not support mixing local-dir and remote-dir, and ForStDB will
498:         // concatenates the dfs directory with the local directory as working dir when using flink
499:         // env. We expect to directly use the dfs directory in flink env or local directory as
500:         // working dir. We will implement this in ForStDB later, but before that, we achieved this
501:         // by setting the dbPath to "/" when the dfs directory existed.
502:         Path instanceForStPath =
503:                 optionsContainer.getRemoteForStPath() == null
504:                         ? optionsContainer.getLocalForStPath()
505:                         : new Path("/db");
506: 
507:         if (CollectionUtil.isEmptyOrAllElementsNull(restoreStateHandles)) {
508:             return new ForStNoneRestoreOperation(
509:                     Collections.emptyMap(),
510:                     instanceForStPath,
511:                     optionsContainer.getDbOptions(),
512:                     columnFamilyOptionsFactory,
513:                     nativeMetricOptions,
514:                     metricGroup,
515:                     ttlCompactFiltersManager,
516:                     writeBatchSize,
517:                     optionsContainer.getWriteBufferManagerCapacity());
518:         }
519:         KeyedStateHandle firstStateHandle = restoreStateHandles.iterator().next();
520:         if (firstStateHandle instanceof IncrementalRemoteKeyedStateHandle) {
521:             return new ForStIncrementalRestoreOperation<>(
522:                     operatorIdentifier,
523:                     keyGroupRange,
524:                     keyGroupPrefixBytes,
525:                     cancelStreamRegistry,
526:                     userCodeClassLoader,
527:                     kvStateInformation,
528:                     keySerializerProvider,
529:                     optionsContainer,
530:                     optionsContainer.getBasePath(),
531:                     instanceForStPath,
532:                     optionsContainer.getDbOptions(),
533:                     columnFamilyOptionsFactory,
534:                     nativeMetricOptions,
535:                     metricGroup,
536:                     ttlCompactFiltersManager,
537:                     writeBatchSize,
538:                     optionsContainer.getWriteBufferManagerCapacity(),
539:                     customInitializationMetrics,
540:                     CollectionUtil.checkedSubTypeCast(
541:                             restoreStateHandles, IncrementalRemoteKeyedStateHandle.class),
542:                     overlapFractionThreshold,
543:                     useIngestDbRestoreMode,
544:                     rescalingUseDeleteFilesInRange,
545:                     recoveryClaimMode);
546:         } else if (priorityQueueConfig.getPriorityQueueStateType()
547:                 == ForStStateBackend.PriorityQueueStateType.HEAP) {
548:             // Note: This branch can be touched after ForSt Support canonical savepoint,
549:             // Timers are stored as raw keyed state instead of managed keyed state now.
550:             return new ForStHeapTimersFullRestoreOperation<>(
551:                     keyGroupRange,
552:                     numberOfKeyGroups,
553:                     userCodeClassLoader,
554:                     kvStateInformation,
555:                     registeredPQStates,
556:                     createHeapQueueFactory(),
557:                     keySerializerProvider,
558:                     instanceForStPath,
559:                     optionsContainer.getDbOptions(),
560:                     columnFamilyOptionsFactory,
561:                     nativeMetricOptions,
562:                     metricGroup,
563:                     ttlCompactFiltersManager,
564:                     writeBatchSize,
565:                     optionsContainer.getWriteBufferManagerCapacity(),
566:                     restoreStateHandles,
567:                     cancelStreamRegistry);
568:         }
569: 
570:         // TODO: Support Restoring
571:         throw new UnsupportedOperationException("Not support restoring yet for ForStStateBackend");
572:     }
