574:     private PriorityQueueSetFactory initPriorityQueueFactory(
575:             int keyGroupPrefixBytes,
576:             Map<String, ForStOperationUtils.ForStKvStateInfo> kvStateInformation,
577:             RocksDB db,
578:             ForStDBWriteBatchWrapper writeBatchWrapper,
579:             ForStNativeMetricMonitor nativeMetricMonitor) {
580:         PriorityQueueSetFactory priorityQueueFactory;
581:         switch (priorityQueueConfig.getPriorityQueueStateType()) {
582:             case HEAP:
583:                 priorityQueueFactory = createHeapQueueFactory();
584:                 break;
585:             case ForStDB:
586:                 priorityQueueFactory =
587:                         new ForStDBPriorityQueueSetFactory(
588:                                 keyGroupRange,
589:                                 keyGroupPrefixBytes,
590:                                 numberOfKeyGroups,
591:                                 kvStateInformation,
592:                                 db,
593:                                 optionsContainer.getReadOptions(),
594:                                 writeBatchWrapper,
595:                                 nativeMetricMonitor,
596:                                 columnFamilyOptionsFactory,
597:                                 optionsContainer.getWriteBufferManagerCapacity(),
598:                                 priorityQueueConfig.getForStDBPriorityQueueSetCacheSize());
599:                 break;
600:             default:
601:                 throw new IllegalArgumentException(
602:                         "Unknown priority queue state type: "
603:                                 + priorityQueueConfig.getPriorityQueueStateType());
