207:     private <N, V> StateTable<K, N, V> tryRegisterStateTable(
208:             TypeSerializer<N> namespaceSerializer,
209:             StateDescriptor<?, V> stateDesc,
210:             @Nonnull StateSnapshotTransformFactory<V> snapshotTransformFactory,
211:             boolean allowFutureMetadataUpdates)
212:             throws StateMigrationException {
213: 
214:         @SuppressWarnings("unchecked")
215:         StateTable<K, N, V> stateTable =
216:                 (StateTable<K, N, V>) registeredKVStates.get(stateDesc.getName());
217: 
218:         TypeSerializer<V> newStateSerializer = stateDesc.getSerializer();
219: 
220:         if (stateTable != null) {
221:             RegisteredKeyValueStateBackendMetaInfo<N, V> restoredKvMetaInfo =
222:                     stateTable.getMetaInfo();
223: 
224:             restoredKvMetaInfo.updateSnapshotTransformFactory(snapshotTransformFactory);
225: 
226:             // fetch current serializer now because if it is incompatible, we can't access
227:             // it anymore to improve the error message
228:             TypeSerializer<N> previousNamespaceSerializer =
229:                     restoredKvMetaInfo.getNamespaceSerializer();
230: 
231:             TypeSerializerSchemaCompatibility<N> namespaceCompatibility =
232:                     restoredKvMetaInfo.updateNamespaceSerializer(namespaceSerializer);
233:             if (namespaceCompatibility.isCompatibleAfterMigration()
234:                     || namespaceCompatibility.isIncompatible()) {
235:                 throw new StateMigrationException(
236:                         "For heap backends, the new namespace serializer ("
237:                                 + namespaceSerializer
238:                                 + ") must be compatible with the old namespace serializer ("
239:                                 + previousNamespaceSerializer
240:                                 + ").");
241:             }
242: 
243:             restoredKvMetaInfo.checkStateMetaInfo(stateDesc);
244: 
245:             // fetch current serializer now because if it is incompatible, we can't access
246:             // it anymore to improve the error message
247:             TypeSerializer<V> previousStateSerializer = restoredKvMetaInfo.getStateSerializer();
248: 
249:             TypeSerializerSchemaCompatibility<V> stateCompatibility =
250:                     restoredKvMetaInfo.updateStateSerializer(newStateSerializer);
251: 
252:             if (stateCompatibility.isIncompatible()) {
253:                 throw new StateMigrationException(
254:                         "For heap backends, the new state serializer ("
255:                                 + newStateSerializer
256:                                 + ") must not be incompatible with the old state serializer ("
257:                                 + previousStateSerializer
258:                                 + ").");
259:             }
260: 
261:             // HeapKeyedStateBackend doesn't support ttl state migration currently.
262:             if (TtlAwareSerializer.needTtlStateMigration(
263:                     previousStateSerializer, newStateSerializer)) {
264:                 throw new StateMigrationException(
265:                         "For heap backends, the new state serializer ("
266:                                 + newStateSerializer
267:                                 + ") must not need ttl state migration with the old state serializer ("
268:                                 + previousStateSerializer
269:                                 + ").");
270:             }
271: 
272:             restoredKvMetaInfo =
273:                     allowFutureMetadataUpdates
274:                             ? restoredKvMetaInfo.withSerializerUpgradesAllowed()
275:                             : restoredKvMetaInfo;
276: 
277:             stateTable.setMetaInfo(restoredKvMetaInfo);
278:         } else {
279:             RegisteredKeyValueStateBackendMetaInfo<N, V> newMetaInfo =
280:                     new RegisteredKeyValueStateBackendMetaInfo<>(
281:                             stateDesc.getType(),
282:                             stateDesc.getName(),
283:                             namespaceSerializer,
284:                             newStateSerializer,
285:                             snapshotTransformFactory);
286: 
287:             newMetaInfo =
288:                     allowFutureMetadataUpdates
289:                             ? newMetaInfo.withSerializerUpgradesAllowed()
290:                             : newMetaInfo;
291: 
292:             stateTable = stateTableFactory.newStateTable(keyContext, newMetaInfo, keySerializer);
293:             registeredKVStates.put(stateDesc.getName(), stateTable);
294:         }
295: 
296:         return stateTable;
297:     }
