311:     @SuppressWarnings("unchecked")
312:     @Override
313:     public <N> Stream<K> getKeys(List<String> states, N namespace) {
314:         final List<StateTable<K, N, ?>> tables =
315:                 states.stream()
316:                         .filter(registeredKVStates::containsKey)
317:                         .map(s -> (StateTable<K, N, ?>) registeredKVStates.get(s))
318:                         .collect(Collectors.toList());
319:         final List<Stream<K>> keyStreams = new ArrayList<>();
320:         for (int i = 0; i < tables.size(); i++) {
321:             int finalI = i;
322:             Stream<K> keyStream =
323:                     StreamSupport.stream(
324:                                     Spliterators.spliteratorUnknownSize(
325:                                             tables.get(i).iterator(), 0),
326:                                     false)
327:                             .filter(
328:                                     entry -> {
329:                                         if (!entry.getNamespace().equals(namespace)) {
330:                                             return false;
331:                                         }
332:                                         // This ensures key deduplication across all table entry
333:                                         // keys
334:                                         for (int j = 0; j < finalI; ++j) {
335:                                             if (tables.get(j)
336:                                                             .get(
337:                                                                     entry.getKey(),
338:                                                                     entry.getNamespace())
339:                                                     != null) {
340:                                                 return false;
341:                                             }
342:                                         }
343:                                         return true;
344:                                     })
345:                             .map(StateEntry::getKey);
346:             keyStreams.add(keyStream);
347:         }
348:         return keyStreams.stream().reduce(Stream.empty(), Stream::concat);
349:     }
