374:     @Override
375:     @Nonnull
376:     public <N, SV, SEV, S extends State, IS extends S> IS createOrUpdateInternalState(
377:             @Nonnull TypeSerializer<N> namespaceSerializer,
378:             @Nonnull StateDescriptor<S, SV> stateDesc,
379:             @Nonnull StateSnapshotTransformFactory<SEV> snapshotTransformFactory,
380:             boolean allowFutureMetadataUpdates)
381:             throws Exception {
382:         StateTable<K, N, SV> stateTable =
383:                 tryRegisterStateTable(
384:                         namespaceSerializer,
385:                         stateDesc,
386:                         getStateSnapshotTransformFactory(stateDesc, snapshotTransformFactory),
387:                         allowFutureMetadataUpdates);
388: 
389:         @SuppressWarnings("unchecked")
390:         IS createdState = (IS) createdKVStates.get(stateDesc.getName());
391:         if (createdState == null) {
392:             StateCreateFactory stateCreateFactory = STATE_CREATE_FACTORIES.get(stateDesc.getType());
393:             if (stateCreateFactory == null) {
394:                 throw new FlinkRuntimeException(stateNotSupportedMessage(stateDesc));
395:             }
396:             createdState =
397:                     stateCreateFactory.createState(stateDesc, stateTable, getKeySerializer());
398:         } else {
399:             StateUpdateFactory stateUpdateFactory = STATE_UPDATE_FACTORIES.get(stateDesc.getType());
400:             if (stateUpdateFactory == null) {
401:                 throw new FlinkRuntimeException(stateNotSupportedMessage(stateDesc));
402:             }
403:             createdState = stateUpdateFactory.updateState(stateDesc, stateTable, createdState);
404:         }
405: 
406:         createdKVStates.put(stateDesc.getName(), createdState);
407:         return createdState;
408:     }
