503:     private SnapshotResult<ChangelogStateBackendHandle> buildSnapshotResult(
504:             long checkpointId,
505:             SnapshotResult<? extends ChangelogStateHandle> delta,
506:             ChangelogSnapshotState changelogStateBackendStateCopy) {
507: 
508:         // collections don't change once started and handles are immutable
509:         List<ChangelogStateHandle> prevDeltaCopy =
510:                 new ArrayList<>(changelogStateBackendStateCopy.getRestoredNonMaterialized());
511:         long persistedSizeOfThisCheckpoint = 0L;
512:         if (delta != null
513:                 && delta.getJobManagerOwnedSnapshot() != null
514:                 && delta.getJobManagerOwnedSnapshot().getStateSize() > 0) {
515:             prevDeltaCopy.add(delta.getJobManagerOwnedSnapshot());
516:             persistedSizeOfThisCheckpoint +=
517:                     delta.getJobManagerOwnedSnapshot().getCheckpointedSize();
518:         }
519: 
520:         if (prevDeltaCopy.isEmpty()
521:                 && changelogStateBackendStateCopy.getMaterializedSnapshot().isEmpty()) {
522:             return SnapshotResult.empty();
523:         } else if ((!isRescaling || hasCompletedMaterialization.get())
524:                 && (!changelogStateBackendStateCopy.getLocalMaterializedSnapshot().isEmpty()
525:                         || delta.getTaskLocalSnapshot() != null)) {
526:             List<ChangelogStateHandle> localDeltaCopy =
527:                     new ArrayList<>(
528:                             changelogStateBackendStateCopy.getLocalRestoredNonMaterialized());
529:             if (delta != null
530:                     && delta.getTaskLocalSnapshot() != null
531:                     && delta.getTaskLocalSnapshot().getStateSize() > 0) {
532:                 localDeltaCopy.add(delta.getTaskLocalSnapshot());
533:             }
534:             ChangelogStateBackendHandleImpl jmHandle =
535:                     new ChangelogStateBackendHandleImpl(
536:                             changelogStateBackendStateCopy.getMaterializedSnapshot(),
537:                             prevDeltaCopy,
538:                             getKeyGroupRange(),
539:                             checkpointId,
540:                             changelogStateBackendStateCopy.materializationID,
541:                             persistedSizeOfThisCheckpoint);
542:             return SnapshotResult.withLocalState(
543:                     jmHandle,
544:                     new ChangelogStateBackendLocalHandle(
545:                             changelogStateBackendStateCopy.getLocalMaterializedSnapshot(),
546:                             localDeltaCopy,
547:                             jmHandle));
548:         } else {
549:             return SnapshotResult.of(
550:                     new ChangelogStateBackendHandleImpl(
551:                             changelogStateBackendStateCopy.getMaterializedSnapshot(),
552:                             prevDeltaCopy,
553:                             getKeyGroupRange(),
554:                             checkpointId,
555:                             changelogStateBackendStateCopy.materializationID,
556:                             persistedSizeOfThisCheckpoint));
