786:     private ChangelogSnapshotState completeRestore(
787:             Collection<ChangelogStateBackendHandle> stateHandles) {
788:         long materializationId = 0L;
789: 
790:         List<KeyedStateHandle> materialized = new ArrayList<>();
791:         List<ChangelogStateHandle> restoredNonMaterialized = new ArrayList<>();
792: 
793:         List<KeyedStateHandle> localMaterialized = new ArrayList<>();
794:         List<ChangelogStateHandle> localRestoredNonMaterialized = new ArrayList<>();
795:         isRescaling = stateHandles.size() > 1;
796:         for (ChangelogStateBackendHandle h : stateHandles) {
797:             if (h != null) {
798:                 if (h instanceof ChangelogStateBackendLocalHandle) {
799:                     ChangelogStateBackendLocalHandle localHandle =
800:                             (ChangelogStateBackendLocalHandle) h;
801:                     materialized.addAll(localHandle.getRemoteMaterializedStateHandles());
802:                     restoredNonMaterialized.addAll(
803:                             localHandle.getRemoteNonMaterializedStateHandles());
804:                     localMaterialized.addAll(localHandle.getMaterializedStateHandles());
805:                     localRestoredNonMaterialized.addAll(
806:                             localHandle.getNonMaterializedStateHandles());
807:                 } else {
808:                     materialized.addAll(h.getMaterializedStateHandles());
809:                     restoredNonMaterialized.addAll(h.getNonMaterializedStateHandles());
810:                 }
811:                 // choose max materializationID to handle rescaling
812:                 materializationId = Math.max(materializationId, h.getMaterializationID());
813:             }
814:         }
815:         this.lastConfirmedMaterializationId = materializationId;
816:         this.materializedId = materializationId + 1;
817: 
818:         if (!isRescaling
819:                 && (!localMaterialized.isEmpty() || !localRestoredNonMaterialized.isEmpty())) {
820:             return new ChangelogSnapshotState(
821:                     materialized,
822:                     localMaterialized,
823:                     restoredNonMaterialized,
824:                     localRestoredNonMaterialized,
825:                     stateChangelogWriter.initialSequenceNumber(),
826:                     materializationId);
827:         }
828:         return new ChangelogSnapshotState(
829:                 materialized,
830:                 restoredNonMaterialized,
831:                 stateChangelogWriter.initialSequenceNumber(),
832:                 materializationId);
833:     }
