835:     /**
836:      * Initialize state materialization so that materialized data can be persisted durably and
837:      * included into the checkpoint.
838:      *
839:      * <p>This method is not thread safe. It should be called either under a lock or through task
840:      * mailbox executor.
841:      *
842:      * @return a tuple of - future snapshot result from the underlying state backend - a {@link
843:      *     SequenceNumber} identifying the latest change in the changelog
844:      */
845:     @Override
846:     public Optional<MaterializationRunnable> initMaterialization() throws Exception {
847:         if (lastConfirmedMaterializationId < materializedId - 1
848:                 && lastFailedMaterializationId < materializedId - 1) {
849:             // SharedStateRegistry potentially requires that the checkpoint's dependency on the
850:             // shared file be continuous, it will be broken if we trigger a new materialization
851:             // before the previous one has either confirmed or failed. See discussion in
852:             // https://github.com/apache/flink/pull/22669#issuecomment-1593370772 .
853:             LOG.info(
854:                     "materialization:{} not confirmed or failed or cancelled, skip trigger new one.",
855:                     materializedId - 1);
856:             return Optional.empty();
857:         }
858: 
859:         SequenceNumber upTo = stateChangelogWriter.nextSequenceNumber();
860:         SequenceNumber lastMaterializedTo = changelogSnapshotState.lastMaterializedTo();
861: 
862:         LOG.info(
863:                 "Initialize Materialization. Current changelog writers last append to sequence number {}",
864:                 upTo);
865: 
866:         if (upTo.compareTo(lastMaterializedTo) > 0) {
867: 
868:             LOG.info("Starting materialization from {} : {}", lastMaterializedTo, upTo);
869: 
870:             // This ID is not needed for materialization; But since we are re-using the
871:             // streamFactory that is designed for state backend snapshot, which requires unique
872:             // checkpoint ID. A faked materialized Id is provided here.
873:             long materializationID = materializedId++;
874: 
875:             MaterializationRunnable materializationRunnable =
876:                     new MaterializationRunnable(
877:                             keyedStateBackend.snapshot(
878:                                     materializationID,
879:                                     System.currentTimeMillis(),
880:                                     // TODO: implement its own streamFactory.
881:                                     streamFactory,
882:                                     CHECKPOINT_OPTIONS),
883:                             materializationID,
884:                             upTo);
885: 
886:             // log metadata after materialization is triggered
887:             changelogStateFactory.resetAllWritingMetaFlags();
888: 
889:             return Optional.of(materializationRunnable);
890:         } else {
891:             LOG.debug(
892:                     "Skip materialization, last materialized to {} : last log to {}",
893:                     lastMaterializedTo,
894:                     upTo);
895: 
896:             return Optional.empty();
897:         }
898:     }
