900:     /**
901:      * This method is not thread safe. It should be called either under a lock or through task
902:      * mailbox executor.
903:      */
904:     @Override
905:     public void handleMaterializationResult(
906:             SnapshotResult<KeyedStateHandle> materializedSnapshot,
907:             long materializationID,
908:             SequenceNumber upTo) {
909: 
910:         LOG.info(
911:                 "Task {} finishes materialization, updates the snapshotState upTo {} : {}",
912:                 subtaskName,
913:                 upTo,
914:                 materializedSnapshot);
915:         changelogSnapshotState =
916:                 materializedSnapshot.getTaskLocalSnapshot() == null
917:                         ? new ChangelogSnapshotState(
918:                                 getMaterializedResult(materializedSnapshot),
919:                                 Collections.emptyList(),
920:                                 upTo,
921:                                 materializationID)
922:                         : new ChangelogSnapshotState(
923:                                 getMaterializedResult(materializedSnapshot),
924:                                 getLocalMaterializedResult(materializedSnapshot),
925:                                 Collections.emptyList(),
926:                                 Collections.emptyList(),
927:                                 upTo,
928:                                 materializationID);
929:         hasCompletedMaterialization.set(true);
930:         changelogTruncateHelper.materialized(upTo);
931:     }
