89: /**
90:  * A {@link org.apache.flink.runtime.state.StateBackend} that stores its state in a ForSt instance.
91:  * This state backend can store very large state that exceeds memory even disk and spills to remote
92:  * storage.
93:  *
94:  * <p>The behavior of the ForSt instances can be parametrized by setting ForSt Options using the
95:  * methods {@link #setForStOptions(ForStOptionsFactory)}.
96:  */
97: @Experimental
98: public class ForStStateBackend extends AbstractManagedMemoryStateBackend
99:         implements ConfigurableStateBackend {
100: 
101:     public static final String CHECKPOINT_DIR_AS_PRIMARY_SHORTCUT = "checkpoint-dir";
102:     public static final String LOCAL_DIR_AS_PRIMARY_SHORTCUT = "local-dir";
103: 
