200:     /** Creates a new {@code ForStStateBackend} for storing state. */
201:     public ForStStateBackend() {
202:         this.enableIncrementalCheckpointing = TernaryBoolean.UNDEFINED;
203:         this.nativeMetricOptions = new ForStNativeMetricOptions();
204:         this.memoryConfiguration = new ForStMemoryConfiguration();
205:         this.priorityQueueConfig = new ForStPriorityQueueConfig();
206:         this.forStMemoryFactory = ForStMemoryFactory.DEFAULT;
207:         this.overlapFractionThreshold = UNDEFINED_OVERLAP_FRACTION_THRESHOLD;
208:         this.useIngestDbRestoreMode = TernaryBoolean.UNDEFINED;
209:         this.rescalingUseDeleteFilesInRange = TernaryBoolean.UNDEFINED;
210:         this.remoteShareWithCheckpoint = false;
211:         this.forceSyncLocal = true;
212:     }
213: 
214:     /**
215:      * Private constructor that creates a re-configured copy of the state backend.
216:      *
217:      * @param original The state backend to re-configure.
218:      * @param config The configuration.
219:      * @param classLoader The class loader.
220:      */
221:     private ForStStateBackend(
222:             ForStStateBackend original, ReadableConfig config, ClassLoader classLoader) {
223:         this.enableIncrementalCheckpointing =
224:                 original.enableIncrementalCheckpointing.resolveUndefined(
225:                         config.get(CheckpointingOptions.INCREMENTAL_CHECKPOINTS));
226:         this.memoryConfiguration =
227:                 ForStMemoryConfiguration.fromOtherAndConfiguration(
228:                         original.memoryConfiguration, config);
229:         this.memoryConfiguration.validate();
230: 
231:         this.remoteShareWithCheckpoint = false;
232:         if (original.remoteForStDirectory != null) {
233:             this.remoteForStDirectory = original.remoteForStDirectory;
234:         } else {
235:             String remoteDirStr = config.get(ForStOptions.PRIMARY_DIRECTORY);
236:             if (CHECKPOINT_DIR_AS_PRIMARY_SHORTCUT.equals(remoteDirStr)) {
237:                 this.remoteForStDirectory = null;
238:                 this.remoteShareWithCheckpoint = true;
239:             } else {
240:                 this.remoteForStDirectory =
241:                         remoteDirStr == null || LOCAL_DIR_AS_PRIMARY_SHORTCUT.equals(remoteDirStr)
242:                                 ? null
243:                                 : new Path(remoteDirStr);
244:             }
245:         }
246:         this.forceSyncLocal = config.get(ForStOptions.SYNC_ENFORCE_LOCAL);
247: 
248:         this.priorityQueueConfig =
249:                 ForStPriorityQueueConfig.fromOtherAndConfiguration(
250:                         original.priorityQueueConfig, config);
251: 
252:         // configure local directories
253:         if (original.localForStDirectories != null) {
254:             this.localForStDirectories = original.localForStDirectories;
255:         } else {
256:             final String forStLocalPaths = config.get(ForStOptions.LOCAL_DIRECTORIES);
257:             if (forStLocalPaths != null) {
258:                 String[] directories = forStLocalPaths.split(",|" + File.pathSeparator);
259: 
260:                 try {
261:                     setLocalDbStoragePaths(directories);
262:                 } catch (IllegalArgumentException e) {
263:                     throw new IllegalConfigurationException(
264:                             "Invalid configuration for ForSt state "
265:                                     + "backend's local storage directories: "
266:                                     + e.getMessage(),
267:                             e);
268:                 }
269:             }
270:         }
271: 
272:         // configure metric options
273:         this.nativeMetricOptions = ForStNativeMetricOptions.fromConfig(config);
274: 
275:         // configurable options
276:         this.configurableOptions = mergeConfigurableOptions(original.configurableOptions, config);
277: 
278:         // configure ForSt options factory
279:         try {
280:             forStOptionsFactory =
281:                     configureOptionsFactory(
282:                             original.forStOptionsFactory,
283:                             config.get(ForStOptions.OPTIONS_FACTORY),
284:                             config,
285:                             classLoader);
286:         } catch (DynamicCodeLoadingException e) {
287:             throw new FlinkRuntimeException(e);
288:         }
289: 
290:         // configure latency tracking
291:         latencyTrackingConfigBuilder = original.latencyTrackingConfigBuilder.configure(config);
292: 
293:         this.forStMemoryFactory = original.forStMemoryFactory;
294: 
295:         // configure overlap fraction threshold
296:         overlapFractionThreshold =
297:                 original.overlapFractionThreshold == UNDEFINED_OVERLAP_FRACTION_THRESHOLD
298:                         ? config.get(RESTORE_OVERLAP_FRACTION_THRESHOLD)
299:                         : original.overlapFractionThreshold;
300: 
301:         checkArgument(
302:                 overlapFractionThreshold >= 0 && this.overlapFractionThreshold <= 1,
303:                 "Overlap fraction threshold of restoring should be between 0 and 1");
304: 
305:         useIngestDbRestoreMode =
306:                 TernaryBoolean.mergeTernaryBooleanWithConfig(
307:                         original.useIngestDbRestoreMode, USE_INGEST_DB_RESTORE_MODE, config);
308: 
309:         rescalingUseDeleteFilesInRange =
310:                 TernaryBoolean.mergeTernaryBooleanWithConfig(
311:                         original.rescalingUseDeleteFilesInRange,
312:                         USE_DELETE_FILES_IN_RANGE_DURING_RESCALING,
313:                         config);
314: 
315:         if (config.getOptional(RESTORE_MODE).isPresent()) {
316:             recoveryClaimMode = config.get(RESTORE_MODE);
317:         }
318:     }
