573:     private ForStOptionsFactory configureOptionsFactory(
574:             @Nullable ForStOptionsFactory originalOptionsFactory,
575:             @Nullable String factoryClassName,
576:             ReadableConfig config,
577:             ClassLoader classLoader)
578:             throws DynamicCodeLoadingException {
579: 
580:         ForStOptionsFactory optionsFactory = null;
581: 
582:         if (originalOptionsFactory != null) {
583:             if (originalOptionsFactory instanceof ConfigurableForStOptionsFactory) {
584:                 originalOptionsFactory =
585:                         ((ConfigurableForStOptionsFactory) originalOptionsFactory)
586:                                 .configure(config);
587:             }
588:             LOG.info("Using application-defined options factory: {}.", originalOptionsFactory);
589: 
590:             optionsFactory = originalOptionsFactory;
591:         } else if (factoryClassName != null) {
592:             try {
593:                 Class<? extends ForStOptionsFactory> clazz =
594:                         Class.forName(factoryClassName, false, classLoader)
595:                                 .asSubclass(ForStOptionsFactory.class);
596: 
597:                 optionsFactory = clazz.newInstance();
598:                 if (optionsFactory instanceof ConfigurableForStOptionsFactory) {
599:                     optionsFactory =
600:                             ((ConfigurableForStOptionsFactory) optionsFactory).configure(config);
601:                 }
602:                 LOG.info("Using configured options factory: {}.", optionsFactory);
603: 
604:             } catch (ClassNotFoundException e) {
605:                 throw new DynamicCodeLoadingException(
606:                         "Cannot find configured options factory class: " + factoryClassName, e);
607:             } catch (ClassCastException | InstantiationException | IllegalAccessException e) {
608:                 throw new DynamicCodeLoadingException(
609:                         "The class configured under '"
610:                                 + ForStOptions.OPTIONS_FACTORY.key()
611:                                 + "' is not a valid options factory ("
612:                                 + factoryClassName
613:                                 + ')',
614:                         e);
615:             }
616:         }
617: 
618:         return optionsFactory;
619:     }
