768:     private ReadableConfig mergeConfigurableOptions(ReadableConfig base, ReadableConfig onTop) {
769:         if (base == null) {
770:             base = new Configuration();
771:         }
772:         Configuration configuration = new Configuration();
773:         Map<String, String> baseMap = base.toMap();
774:         Map<String, String> onTopMap = onTop.toMap();
775:         for (ConfigOption<?> option : ForStConfigurableOptions.CANDIDATE_CONFIGS) {
776:             Optional<?> baseValue = base.getOptional(option);
777:             Optional<?> topValue = onTop.getOptional(option);
778: 
779:             if (topValue.isPresent() || baseValue.isPresent()) {
780:                 Object validValue = topValue.isPresent() ? topValue.get() : baseValue.get();
781:                 ForStConfigurableOptions.checkArgumentValid(option, validValue);
782:                 configuration.setString(option.key(), validValue.toString());
783:                 String valueString =
784:                         topValue.isPresent()
785:                                 ? onTopMap.get(option.key())
786:                                 : baseMap.get(option.key());
787:                 configuration.setString(option.key(), valueString);
788:             }
789:         }
790:         return configuration;
791:     }
