793:     Tuple2<Path, Path> getForStBasePath(String operatorIdentifier, Environment env) {
794:         String opChildPath =
795:                 String.format(
796:                         "op_%s_attempt_%s",
797:                         operatorIdentifier, env.getTaskInfo().getAttemptNumber());
798: 
799:         Path localBasePath =
800:                 new Path(
801:                         new File(new File(getNextStoragePath(), jobId.toHexString()), opChildPath)
802:                                 .getAbsolutePath());
803:         Path remoteBasePath = null;
804:         if (remoteForStDirectory != null) {
805:             remoteBasePath =
806:                     new Path(new Path(remoteForStDirectory, jobId.toHexString()), opChildPath);
807:         } else if (remoteShareWithCheckpoint) {
808:             if (env.getCheckpointStorageAccess() instanceof FsCheckpointStorageAccess) {
809:                 Path sharedStateDirectory =
810:                         ((FsCheckpointStorageAccess) env.getCheckpointStorageAccess())
811:                                 .getSharedStateDirectory();
812:                 remoteBasePath = new Path(sharedStateDirectory, opChildPath);
813:                 LOG.info("Set remote ForSt directory to checkpoint directory {}", remoteBasePath);
814:             } else {
815:                 LOG.warn(
816:                         "Remote ForSt directory can't be set, because checkpoint directory isn't on file system.");
817:             }
818:         }
819:         return Tuple2.of(localBasePath, remoteBasePath);
820:     }
