528:     /** Should only be called by one thread, and only after all accesses to the DB happened. */
529:     @Override
530:     public void dispose() {
531:         if (this.disposed) {
532:             return;
533:         }
534:         super.dispose();
535: 
536:         IOUtils.closeQuietly(sstMergeManager);
537: 
538:         // This call will block until all clients that still acquire access to the RocksDB instance
539:         // have released it,
540:         // so that we cannot release the native resources while clients are still working with it in
541:         // parallel.
542:         rocksDBResourceGuard.close();
543: 
544:         // IMPORTANT: null reference to signal potential async checkpoint workers that the db was
545:         // disposed, as
546:         // working on the disposed object results in SEGFAULTS.
547:         if (db != null) {
548:             IOUtils.closeQuietly(writeBatchWrapper);
549: 
550:             // Metric collection occurs on a background thread. When this method returns
551:             // it is guaranteed that thr RocksDB reference has been invalidated
552:             // and no more metric collection will be attempted against the database.
553:             if (nativeMetricMonitor != null) {
554:                 nativeMetricMonitor.close();
555:             }
556: 
557:             List<ColumnFamilyOptions> columnFamilyOptions =
558:                     new ArrayList<>(kvStateInformation.values().size());
559: 
560:             // RocksDB's native memory management requires that *all* CFs (including default) are
561:             // closed before the
562:             // DB is closed. See:
563:             // https://github.com/facebook/rocksdb/wiki/RocksJava-Basics#opening-a-database-with-column-families
564:             // Start with default CF ...
565:             RocksDBOperationUtils.addColumnFamilyOptionsToCloseLater(
566:                     columnFamilyOptions, defaultColumnFamily);
567:             IOUtils.closeQuietly(defaultColumnFamily);
568: 
569:             // ... continue with the ones created by Flink...
570:             for (RocksDbKvStateInfo kvStateInfo : kvStateInformation.values()) {
571:                 RocksDBOperationUtils.addColumnFamilyOptionsToCloseLater(
572:                         columnFamilyOptions, kvStateInfo.columnFamilyHandle);
573:                 IOUtils.closeQuietly(kvStateInfo.columnFamilyHandle);
574:             }
575: 
576:             // ... and finally close the DB instance ...
577:             IOUtils.closeQuietly(db);
578: 
579:             columnFamilyOptions.forEach(IOUtils::closeQuietly);
580: 
581:             IOUtils.closeQuietly(optionsContainer);
582: 
583:             ttlCompactFiltersManager.disposeAndClearRegisteredCompactionFactories();
584: 
585:             kvStateInformation.clear();
586: 
587:             cleanInstanceBasePath();
588:         }
589:         IOUtils.closeQuietly(checkpointSnapshotStrategy);
590:         this.disposed = true;
591:     }
