674:             final long checkpointId,
675:             final long timestamp,
676:             @Nonnull final CheckpointStreamFactory streamFactory,
677:             @Nonnull CheckpointOptions checkpointOptions)
678:             throws Exception {
679: 
680:         // flush everything into db before taking a snapshot
681:         writeBatchWrapper.flush();
682: 
683:         return new SnapshotStrategyRunner<>(
684:                         checkpointSnapshotStrategy.getDescription(),
685:                         checkpointSnapshotStrategy,
686:                         cancelStreamRegistry,
687:                         ASYNCHRONOUS)
688:                 .snapshot(checkpointId, timestamp, streamFactory, checkpointOptions);
689:     }
