732:     /**
733:      * Registers a k/v state information, which includes its state id, type, RocksDB column family
734:      * handle, and serializers.
735:      *
736:      * <p>When restoring from a snapshot, we don’t restore the individual k/v states, just the
737:      * global RocksDB database and the list of k/v state information. When a k/v state is first
738:      * requested we check here whether we already have a registered entry for that and return it
739:      * (after some necessary state compatibility checks) or create a new one if it does not exist.
740:      */
741:     private <N, S extends State, SV, SEV>
742:             Tuple2<ColumnFamilyHandle, RegisteredKeyValueStateBackendMetaInfo<N, SV>>
743:                     tryRegisterKvStateInformation(
744:                             StateDescriptor<S, SV> stateDesc,
745:                             TypeSerializer<N> namespaceSerializer,
746:                             @Nonnull StateSnapshotTransformFactory<SEV> snapshotTransformFactory,
747:                             boolean allowFutureMetadataUpdates)
748:                             throws Exception {
749: 
750:         RocksDbKvStateInfo oldStateInfo = kvStateInformation.get(stateDesc.getName());
751: 
752:         TypeSerializer<SV> stateSerializer = stateDesc.getSerializer();
753: 
754:         RocksDbKvStateInfo newRocksStateInfo;
755:         RegisteredKeyValueStateBackendMetaInfo<N, SV> newMetaInfo;
756:         if (oldStateInfo != null) {
757:             @SuppressWarnings("unchecked")
758:             RegisteredKeyValueStateBackendMetaInfo<N, SV> castedMetaInfo =
759:                     (RegisteredKeyValueStateBackendMetaInfo<N, SV>) oldStateInfo.metaInfo;
760: 
761:             Tuple2<ColumnFamilyHandle, RegisteredKeyValueStateBackendMetaInfo<N, SV>>
762:                     newRocksDBState =
763:                             updateRestoredStateMetaInfo(
764:                                     Tuple2.of(oldStateInfo.columnFamilyHandle, castedMetaInfo),
765:                                     stateDesc,
766:                                     namespaceSerializer,
767:                                     stateSerializer);
768:             newMetaInfo = newRocksDBState.f1;
769:             newMetaInfo =
770:                     allowFutureMetadataUpdates
771:                             ? newMetaInfo.withSerializerUpgradesAllowed()
772:                             : newMetaInfo;
773: 
774:             newRocksStateInfo = new RocksDbKvStateInfo(newRocksDBState.f0, newMetaInfo);
775:             kvStateInformation.put(stateDesc.getName(), newRocksStateInfo);
776:             sstMergeManager.register(newRocksStateInfo);
777:         } else {
778:             newMetaInfo =
779:                     new RegisteredKeyValueStateBackendMetaInfo<>(
780:                             stateDesc.getType(),
781:                             stateDesc.getName(),
782:                             namespaceSerializer,
783:                             stateSerializer,
784:                             StateSnapshotTransformFactory.noTransform());
785: 
786:             newMetaInfo =
787:                     allowFutureMetadataUpdates
788:                             ? newMetaInfo.withSerializerUpgradesAllowed()
789:                             : newMetaInfo;
790: 
791:             newRocksStateInfo =
792:                     RocksDBOperationUtils.createStateInfo(
793:                             newMetaInfo,
794:                             db,
795:                             columnFamilyOptionsFactory,
796:                             ttlCompactFiltersManager,
797:                             optionsContainer.getWriteBufferManagerCapacity(),
798:                             // Using ICloseableRegistry.NO_OP here because there is no restore in
799:                             // progress; created column families will be closed in dispose()
800:                             ICloseableRegistry.NO_OP);
801:             RocksDBOperationUtils.registerKvStateInformation(
802:                     this.kvStateInformation,
803:                     this.nativeMetricMonitor,
804:                     stateDesc.getName(),
805:                     newRocksStateInfo);
806:             sstMergeManager.register(newRocksStateInfo);
807:         }
808: 
809:         StateSnapshotTransformFactory<SV> wrappedSnapshotTransformFactory =
810:                 wrapStateSnapshotTransformFactory(
811:                         stateDesc, snapshotTransformFactory, newMetaInfo.getStateSerializer());
812:         newMetaInfo.updateSnapshotTransformFactory(wrappedSnapshotTransformFactory);
813: 
814:         return Tuple2.of(newRocksStateInfo.columnFamilyHandle, newMetaInfo);
815:     }
816: 
817:     private <N, S extends State, SV>
818:             Tuple2<ColumnFamilyHandle, RegisteredKeyValueStateBackendMetaInfo<N, SV>>
819:                     updateRestoredStateMetaInfo(
820:                             Tuple2<
821:                                             ColumnFamilyHandle,
822:                                             RegisteredKeyValueStateBackendMetaInfo<N, SV>>
823:                                     oldStateInfo,
824:                             StateDescriptor<S, SV> stateDesc,
825:                             TypeSerializer<N> namespaceSerializer,
826:                             TypeSerializer<SV> stateSerializer)
827:                             throws Exception {
828: 
829:         RegisteredKeyValueStateBackendMetaInfo<N, SV> restoredKvStateMetaInfo = oldStateInfo.f1;
830: 
831:         // fetch current serializer now because if it is incompatible, we can't access
832:         // it anymore to improve the error message
833:         TypeSerializer<N> previousNamespaceSerializer =
834:                 restoredKvStateMetaInfo.getNamespaceSerializer();
835: 
836:         TypeSerializerSchemaCompatibility<N> s =
837:                 restoredKvStateMetaInfo.updateNamespaceSerializer(namespaceSerializer);
838:         if (s.isCompatibleAfterMigration() || s.isIncompatible()) {
839:             throw new StateMigrationException(
840:                     "The new namespace serializer ("
841:                             + namespaceSerializer
842:                             + ") must be compatible with the old namespace serializer ("
843:                             + previousNamespaceSerializer
844:                             + ").");
845:         }
846: 
847:         restoredKvStateMetaInfo.checkStateMetaInfo(stateDesc);
848: 
849:         // fetch current serializer now because if it is incompatible, we can't access
850:         // it anymore to improve the error message
851:         TypeSerializer<SV> previousStateSerializer = restoredKvStateMetaInfo.getStateSerializer();
852: 
853:         TypeSerializerSchemaCompatibility<SV> newStateSerializerCompatibility =
854:                 restoredKvStateMetaInfo.updateStateSerializer(stateSerializer);
855:         if (newStateSerializerCompatibility.isCompatibleAfterMigration()) {
856:             migrateStateValues(stateDesc, oldStateInfo);
857:         } else if (newStateSerializerCompatibility.isIncompatible()) {
858:             throw new StateMigrationException(
859:                     "The new state serializer ("
860:                             + stateSerializer
861:                             + ") must not be incompatible with the old state serializer ("
862:                             + previousStateSerializer
863:                             + ").");
864:         }
865: 
866:         return oldStateInfo;
867:     }
868: 
869:     /**
870:      * Migrate only the state value, that is the "value" that is stored in RocksDB. We don't migrate
871:      * the key here, which is made up of key group, key, namespace and map key (in case of
872:      * MapState).
873:      */
874:     @SuppressWarnings("unchecked")
875:     private <N, S extends State, SV> void migrateStateValues(
876:             StateDescriptor<S, SV> stateDesc,
877:             Tuple2<ColumnFamilyHandle, RegisteredKeyValueStateBackendMetaInfo<N, SV>> stateMetaInfo)
878:             throws Exception {
879: 
880:         if (stateDesc.getType() == StateDescriptor.Type.MAP) {
881:             TypeSerializerSnapshot<SV> previousSerializerSnapshot =
882:                     stateMetaInfo.f1.getPreviousStateSerializerSnapshot();
883:             checkState(
884:                     previousSerializerSnapshot != null,
885:                     "the previous serializer snapshot should exist.");
886:             checkState(
887:                     previousSerializerSnapshot instanceof MapSerializerSnapshot,
888:                     "previous serializer snapshot should be a MapSerializerSnapshot.");
889: 
890:             TypeSerializer<SV> newSerializer = stateMetaInfo.f1.getStateSerializer();
891:             checkState(
892:                     newSerializer instanceof MapSerializer,
893:                     "new serializer should be a MapSerializer.");
894: 
895:             MapSerializer<?, ?> mapSerializer = (MapSerializer<?, ?>) newSerializer;
896:             MapSerializerSnapshot<?, ?> mapSerializerSnapshot =
897:                     (MapSerializerSnapshot<?, ?>) previousSerializerSnapshot;
898:             if (!checkMapStateKeySchemaCompatibility(mapSerializerSnapshot, mapSerializer)) {
899:                 throw new StateMigrationException(
900:                         "The new serializer for a MapState requires state migration in order for the job to proceed, since the key schema has changed. However, migration for MapState currently only allows value schema evolutions.");
901:             }
902:         }
903: 
904:         LOG.info(
905:                 "Performing state migration for state {} because the state serializer's schema, i.e. serialization format, has changed.",
906:                 stateDesc);
907: 
908:         // we need to get an actual state instance because migration is different
909:         // for different state types. For example, ListState needs to deal with
910:         // individual elements
911:         State state = createState(stateDesc, stateMetaInfo);
912:         if (!(state instanceof AbstractRocksDBState)) {
913:             throw new FlinkRuntimeException(
914:                     "State should be an AbstractRocksDBState but is " + state);
915:         }
916: 
917:         @SuppressWarnings("unchecked")
918:         AbstractRocksDBState<?, ?, SV> rocksDBState = (AbstractRocksDBState<?, ?, SV>) state;
919: 
920:         Snapshot rocksDBSnapshot = db.getSnapshot();
921:         try (RocksIteratorWrapper iterator =
922:                         RocksDBOperationUtils.getRocksIterator(db, stateMetaInfo.f0, readOptions);
923:                 RocksDBWriteBatchWrapper batchWriter =
924:                         new RocksDBWriteBatchWrapper(db, getWriteOptions(), getWriteBatchSize());
925:                 Closeable ignored =
926:                         cancelStreamRegistry.registerCloseableTemporarily(
927:                                 writeBatchWrapper.getCancelCloseable())) {
928:             iterator.seekToFirst();
929: 
930:             DataInputDeserializer serializedValueInput = new DataInputDeserializer();
931:             DataOutputSerializer migratedSerializedValueOutput = new DataOutputSerializer(512);
932: 
933:             // Check if this is ttl state migration
934:             TtlAwareSerializer<SV, ?> previousTtlAwareSerializer =
935:                     (TtlAwareSerializer<SV, ?>)
936:                             TtlAwareSerializer.wrapTtlAwareSerializer(
937:                                     stateMetaInfo.f1.getPreviousStateSerializer());
938:             TtlAwareSerializer<SV, ?> currentTtlAwareSerializer =
939:                     (TtlAwareSerializer<SV, ?>)
940:                             TtlAwareSerializer.wrapTtlAwareSerializer(
941:                                     stateMetaInfo.f1.getStateSerializer());
942: 
943:             if (TtlAwareSerializer.needTtlStateMigration(
944:                     previousTtlAwareSerializer, currentTtlAwareSerializer)) {
945:                 // By performing ttl state migration, we need to recreate column family to
946:                 // enable/disable ttl compaction filter factory.
947:                 db.dropColumnFamily(stateMetaInfo.f0);
948:                 stateMetaInfo.f0 =
949:                         RocksDBOperationUtils.createColumnFamily(
950:                                 RocksDBOperationUtils.createColumnFamilyDescriptor(
951:                                         stateMetaInfo.f1,
952:                                         columnFamilyOptionsFactory,
953:                                         ttlCompactFiltersManager,
954:                                         optionsContainer.getWriteBufferManagerCapacity()),
955:                                 db,
956:                                 Collections.emptyList(),
957:                                 ICloseableRegistry.NO_OP);
958:             }
959: 
960:             while (iterator.isValid()) {
961:                 serializedValueInput.setBuffer(iterator.value());
962: 
963:                 rocksDBState.migrateSerializedValue(
964:                         serializedValueInput,
965:                         migratedSerializedValueOutput,
966:                         previousTtlAwareSerializer,
967:                         currentTtlAwareSerializer,
968:                         this.ttlTimeProvider);
969: 
970:                 batchWriter.put(
971:                         stateMetaInfo.f0,
972:                         iterator.key(),
973:                         migratedSerializedValueOutput.getCopyOfBuffer());
974: 
975:                 migratedSerializedValueOutput.clear();
976:                 iterator.next();
977:             }
978:         } finally {
979:             db.releaseSnapshot(rocksDBSnapshot);
980:             rocksDBSnapshot.close();
981:         }
982:     }
