1034:     private <N, SV, S extends State, IS extends S> IS createState(
1035:             StateDescriptor<S, SV> stateDesc,
1036:             Tuple2<ColumnFamilyHandle, RegisteredKeyValueStateBackendMetaInfo<N, SV>>
1037:                     registerResult)
1038:             throws Exception {
1039:         @SuppressWarnings("unchecked")
1040:         IS createdState = (IS) createdKVStates.get(stateDesc.getName());
1041:         if (createdState == null) {
1042:             StateCreateFactory stateCreateFactory = STATE_CREATE_FACTORIES.get(stateDesc.getType());
1043:             if (stateCreateFactory == null) {
1044:                 throw new FlinkRuntimeException(stateNotSupportedMessage(stateDesc));
1045:             }
1046:             createdState =
1047:                     stateCreateFactory.createState(
1048:                             stateDesc, registerResult, RocksDBKeyedStateBackend.this);
1049:         } else {
1050:             StateUpdateFactory stateUpdateFactory = STATE_UPDATE_FACTORIES.get(stateDesc.getType());
1051:             if (stateUpdateFactory == null) {
1052:                 throw new FlinkRuntimeException(stateNotSupportedMessage(stateDesc));
1053:             }
1054:             createdState = stateUpdateFactory.updateState(stateDesc, registerResult, createdState);
1055:         }
1056: 
1057:         createdKVStates.put(stateDesc.getName(), createdState);
1058:         return createdState;
1059:     }
