387:     private void lazyInitializeForJob(
388:             Environment env, @SuppressWarnings("unused") String operatorIdentifier)
389:             throws IOException {
390: 
391:         if (isInitialized) {
392:             return;
393:         }
394: 
395:         this.jobId = env.getJobID();
396: 
397:         // initialize the paths where the local RocksDB files should be stored
398:         if (localRocksDbDirectories == null) {
399:             initializedDbBasePaths = new File[] {env.getTaskManagerInfo().getTmpWorkingDirectory()};
400:         } else {
401:             List<File> dirs = new ArrayList<>(localRocksDbDirectories.length);
402:             StringBuilder errorMessage = new StringBuilder();
403: 
404:             for (File f : localRocksDbDirectories) {
405:                 File testDir = new File(f, UUID.randomUUID().toString());
406:                 if (!testDir.mkdirs()) {
407:                     String msg =
408:                             "Local DB files directory '"
409:                                     + f
410:                                     + "' does not exist and cannot be created. ";
411:                     LOG.error(msg);
412:                     errorMessage.append(msg);
413:                 } else {
414:                     dirs.add(f);
415:                 }
416:                 //noinspection ResultOfMethodCallIgnored
417:                 testDir.delete();
418:             }
419: 
420:             if (dirs.isEmpty()) {
421:                 throw new IOException("No local storage directories available. " + errorMessage);
422:             } else {
423:                 initializedDbBasePaths = dirs.toArray(new File[0]);
424:             }
425:         }
426: 
427:         nextDirectory = new Random().nextInt(initializedDbBasePaths.length);
428: 
429:         isInitialized = true;
430:     }
431: 
432:     private File getNextStoragePath() {
433:         int ni = nextDirectory + 1;
434:         ni = ni >= initializedDbBasePaths.length ? 0 : ni;
435:         nextDirectory = ni;
436: 
437:         return initializedDbBasePaths[ni];
438:     }
