628:     /**
629:      * Sets the directories in which the local RocksDB database puts its files (like SST and
630:      * metadata files). These directories do not need to be persistent, they can be ephemeral,
631:      * meaning that they are lost on a machine failure, because state in RocksDB is persisted in
632:      * checkpoints.
633:      *
634:      * <p>If nothing is configured, these directories default to the TaskManager's local temporary
635:      * file directories.
636:      *
637:      * <p>Each distinct state will be stored in one path, but when the state backend creates
638:      * multiple states, they will store their files on different paths.
639:      *
640:      * <p>Passing {@code null} to this function restores the default behavior, where the configured
641:      * temp directories will be used.
642:      *
643:      * @param paths The paths across which the local RocksDB database files will be spread.
644:      */
645:     public void setDbStoragePaths(String... paths) {
646:         if (paths == null) {
647:             localRocksDbDirectories = null;
648:         } else if (paths.length == 0) {
649:             throw new IllegalArgumentException("empty paths");
650:         } else {
651:             File[] pp = new File[paths.length];
652: 
653:             for (int i = 0; i < paths.length; i++) {
654:                 final String rawPath = paths[i];
655:                 final String path;
656: 
657:                 if (rawPath == null) {
658:                     throw new IllegalArgumentException("null path");
659:                 } else {
660:                     // we need this for backwards compatibility, to allow URIs like 'file:///'...
661:                     URI uri = null;
662:                     try {
663:                         uri = new Path(rawPath).toUri();
664:                     } catch (Exception e) {
665:                         // cannot parse as a path
666:                     }
667: 
668:                     if (uri != null && uri.getScheme() != null) {
669:                         if ("file".equalsIgnoreCase(uri.getScheme())) {
670:                             path = uri.getPath();
671:                         } else {
672:                             throw new IllegalArgumentException(
673:                                     "Path " + rawPath + " has a non-local scheme");
674:                         }
675:                     } else {
676:                         path = rawPath;
677:                     }
678:                 }
679: 
680:                 pp[i] = new File(path);
681:                 if (!pp[i].isAbsolute()) {
682:                     throw new IllegalArgumentException("Relative paths are not supported");
683:                 }
684:             }
685: 
686:             localRocksDbDirectories = pp;
687:         }
688:     }
