935: 
936:     @VisibleForTesting
937:     static void ensureRocksDBIsLoaded(
938:             String tempDirectory, Supplier<NativeLibraryLoader> nativeLibraryLoaderSupplier)
939:             throws IOException {
940:         synchronized (EmbeddedRocksDBStateBackend.class) {
941:             if (!rocksDbInitialized) {
942: 
943:                 final File tempDirParent = new File(tempDirectory).getAbsoluteFile();
944:                 LOG.info(
945:                         "Attempting to load RocksDB native library and store it under '{}'",
946:                         tempDirParent);
947: 
948:                 Throwable lastException = null;
949:                 for (int attempt = 1; attempt <= ROCKSDB_LIB_LOADING_ATTEMPTS; attempt++) {
950:                     File rocksLibFolder = null;
951:                     try {
952:                         // when multiple instances of this class and RocksDB exist in different
953:                         // class loaders, then we can see the following exception:
954:                         // "java.lang.UnsatisfiedLinkError: Native Library
955:                         // /path/to/temp/dir/librocksdbjni-linux64.so
956:                         // already loaded in another class loader"
957: 
958:                         // to avoid that, we need to add a random element to the library file path
959:                         // (I know, seems like an unnecessary hack, since the JVM obviously can
960:                         // handle multiple
961:                         //  instances of the same JNI library being loaded in different class
962:                         // loaders, but
963:                         //  apparently not when coming from the same file path, so there we go)
964: 
965:                         rocksLibFolder = new File(tempDirParent, "rocksdb-lib-" + new AbstractID());
966: 
967:                         // make sure the temp path exists
968:                         LOG.debug(
969:                                 "Attempting to create RocksDB native library folder {}",
970:                                 rocksLibFolder);
971:                         // noinspection ResultOfMethodCallIgnored
972:                         rocksLibFolder.mkdirs();
973: 
974:                         // explicitly load the JNI dependency if it has not been loaded before
975:                         nativeLibraryLoaderSupplier
976:                                 .get()
977:                                 .loadLibrary(rocksLibFolder.getAbsolutePath());
978: 
979:                         // this initialization here should validate that the loading succeeded
980:                         RocksDB.loadLibrary();
981: 
982:                         // seems to have worked
983:                         LOG.info("Successfully loaded RocksDB native library");
984:                         rocksDbInitialized = true;
985:                         return;
986:                     } catch (Throwable t) {
987:                         lastException = t;
988:                         LOG.debug("RocksDB JNI library loading attempt {} failed", attempt, t);
989: 
990:                         // try to force RocksDB to attempt reloading the library
991:                         try {
992:                             resetRocksDBLoadedFlag();
993:                         } catch (Throwable tt) {
994:                             LOG.debug(
995:                                     "Failed to reset 'initialized' flag in RocksDB native code loader",
996:                                     tt);
997:                         }
998: 
999:                         FileUtils.deleteDirectoryQuietly(rocksLibFolder);
1000:                     }
1001:                 }
1002: 
1003:                 throw new IOException("Could not load the native RocksDB library", lastException);
1004:             }
1005:         }
1006:     }
1007: 
1008:     @VisibleForTesting
1009:     static void resetRocksDBLoadedFlag() throws Exception {
1010:         final Field initField =
1011:                 org.rocksdb.NativeLibraryLoader.class.getDeclaredField("initialized");
1012:         initField.setAccessible(true);
1013:         initField.setBoolean(null, false);
1014:     }
