238:     /**
239:      * Private constructor that creates a re-configured copy of the state backend.
240:      *
241:      * @param original The state backend to re-configure.
242:      * @param config The configuration.
243:      * @param classLoader The class loader.
244:      */
245:     protected EmbeddedRocksDBStateBackend(
246:             EmbeddedRocksDBStateBackend original, ReadableConfig config, ClassLoader classLoader) {
247:         // configure incremental checkpoints
248:         this.enableIncrementalCheckpointing =
249:                 original.enableIncrementalCheckpointing.resolveUndefined(
250:                         config.get(CheckpointingOptions.INCREMENTAL_CHECKPOINTS));
251: 
252:         if (original.numberOfTransferThreads == UNDEFINED_NUMBER_OF_TRANSFER_THREADS) {
253:             this.numberOfTransferThreads = config.get(CHECKPOINT_TRANSFER_THREAD_NUM);
254:         } else {
255:             this.numberOfTransferThreads = original.numberOfTransferThreads;
256:         }
257: 
258:         if (original.writeBatchSize == UNDEFINED_WRITE_BATCH_SIZE) {
259:             this.writeBatchSize = config.get(WRITE_BATCH_SIZE).getBytes();
260:         } else {
261:             this.writeBatchSize = original.writeBatchSize;
262:         }
263: 
264:         this.memoryConfiguration =
265:                 RocksDBMemoryConfiguration.fromOtherAndConfiguration(
266:                         original.memoryConfiguration, config);
267:         this.memoryConfiguration.validate();
268: 
269:         this.priorityQueueConfig =
270:                 RocksDBPriorityQueueConfig.fromOtherAndConfiguration(
271:                         original.priorityQueueConfig, config);
272: 
273:         // configure local directories
274:         if (original.localRocksDbDirectories != null) {
275:             this.localRocksDbDirectories = original.localRocksDbDirectories;
276:         } else {
277:             final String rocksdbLocalPaths = config.get(RocksDBOptions.LOCAL_DIRECTORIES);
278:             if (rocksdbLocalPaths != null) {
279:                 String[] directories = rocksdbLocalPaths.split(",|" + File.pathSeparator);
280: 
281:                 try {
282:                     setDbStoragePaths(directories);
283:                 } catch (IllegalArgumentException e) {
284:                     throw new IllegalConfigurationException(
285:                             "Invalid configuration for RocksDB state "
286:                                     + "backend's local storage directories: "
287:                                     + e.getMessage(),
288:                             e);
289:                 }
290:             }
291:         }
292: 
293:         // configure metric options
294:         this.nativeMetricOptions = RocksDBNativeMetricOptions.fromConfig(config);
295: 
296:         // configure RocksDB predefined options
297:         this.predefinedOptions =
298:                 original.predefinedOptions == null
299:                         ? PredefinedOptions.valueOf(config.get(RocksDBOptions.PREDEFINED_OPTIONS))
300:                         : original.predefinedOptions;
301:         LOG.info("Using predefined options: {}.", predefinedOptions.name());
302: 
303:         // configurable options
304:         this.configurableOptions = mergeConfigurableOptions(original.configurableOptions, config);
305: 
306:         // configure RocksDB options factory
307:         try {
308:             rocksDbOptionsFactory =
309:                     configureOptionsFactory(
310:                             original.rocksDbOptionsFactory,
311:                             config.get(RocksDBOptions.OPTIONS_FACTORY),
312:                             config,
313:                             classLoader);
314:         } catch (DynamicCodeLoadingException e) {
315:             throw new FlinkRuntimeException(e);
316:         }
317: 
318:         // configure latency tracking
319:         metricsTrackingConfigBuilder = original.metricsTrackingConfigBuilder.configure(config);
320: 
321:         // configure overlap fraction threshold
322:         overlapFractionThreshold =
323:                 original.overlapFractionThreshold == UNDEFINED_OVERLAP_FRACTION_THRESHOLD
324:                         ? config.get(RESTORE_OVERLAP_FRACTION_THRESHOLD)
325:                         : original.overlapFractionThreshold;
326:         checkArgument(
327:                 overlapFractionThreshold >= 0 && this.overlapFractionThreshold <= 1,
328:                 "Overlap fraction threshold of restoring should be between 0 and 1");
329: 
330:         incrementalRestoreAsyncCompactAfterRescale =
331:                 TernaryBoolean.mergeTernaryBooleanWithConfig(
332:                         original.incrementalRestoreAsyncCompactAfterRescale,
333:                         INCREMENTAL_RESTORE_ASYNC_COMPACT_AFTER_RESCALE,
334:                         config);
335: 
336:         useIngestDbRestoreMode =
337:                 TernaryBoolean.mergeTernaryBooleanWithConfig(
338:                         original.useIngestDbRestoreMode, USE_INGEST_DB_RESTORE_MODE, config);
339: 
340:         rescalingUseDeleteFilesInRange =
341:                 TernaryBoolean.mergeTernaryBooleanWithConfig(
342:                         original.rescalingUseDeleteFilesInRange,
343:                         USE_DELETE_FILES_IN_RANGE_DURING_RESCALING,
344:                         config);
345: 
346:         this.rocksDBMemoryFactory = original.rocksDBMemoryFactory;
347: 
348:         this.manualCompactionConfig =
349:                 original.manualCompactionConfig != null
350:                         ? original.manualCompactionConfig
351:                         : RocksDBManualCompactionConfig.from(config);
352:     }
