444:     @Override
445:     public <K> AbstractKeyedStateBackend<K> createKeyedStateBackend(
446:             KeyedStateBackendParameters<K> parameters) throws IOException {
447:         Environment env = parameters.getEnv();
448: 
449:         // first, make sure that the RocksDB JNI library is loaded
450:         // we do this explicitly here to have better error handling
451:         String tempDir = env.getTaskManagerInfo().getTmpWorkingDirectory().getAbsolutePath();
452:         ensureRocksDBIsLoaded(tempDir);
453: 
454:         // replace all characters that are not legal for filenames with underscore
455:         String fileCompatibleIdentifier =
456:                 parameters.getOperatorIdentifier().replaceAll("[^a-zA-Z0-9\\-]", "_");
457: 
458:         lazyInitializeForJob(env, fileCompatibleIdentifier);
459: 
460:         File instanceBasePath =
461:                 new File(
462:                         getNextStoragePath(),
463:                         "job_"
464:                                 + jobId
465:                                 + "_op_"
466:                                 + fileCompatibleIdentifier
467:                                 + "_uuid_"
468:                                 + UUID.randomUUID());
469: 
470:         LocalRecoveryConfig localRecoveryConfig =
471:                 env.getTaskStateManager().createLocalRecoveryConfig();
472: 
473:         final OpaqueMemoryResource<RocksDBSharedResources> sharedResources =
474:                 RocksDBOperationUtils.allocateSharedCachesIfConfigured(
475:                         memoryConfiguration,
476:                         env,
477:                         parameters.getManagedMemoryFraction(),
478:                         LOG,
479:                         rocksDBMemoryFactory);
480:         if (sharedResources != null) {
481:             LOG.info("Obtained shared RocksDB cache of size {} bytes", sharedResources.getSize());
482:         }
483:         final RocksDBResourceContainer resourceContainer =
484:                 createOptionsAndResourceContainer(
485:                         sharedResources,
486:                         instanceBasePath,
487:                         nativeMetricOptions.isStatisticsEnabled());
488: 
489:         ExecutionConfig executionConfig = env.getExecutionConfig();
490:         StreamCompressionDecorator keyGroupCompressionDecorator =
491:                 getCompressionDecorator(executionConfig);
492: 
493:         MetricsTrackingStateConfig metricsTrackingStateConfig =
494:                 metricsTrackingConfigBuilder.setMetricGroup(parameters.getMetricGroup()).build();
495:         RocksDBKeyedStateBackendBuilder<K> builder =
496:                 new RocksDBKeyedStateBackendBuilder<>(
497:                                 parameters.getOperatorIdentifier(),
498:                                 env.getUserCodeClassLoader().asClassLoader(),
499:                                 instanceBasePath,
500:                                 resourceContainer,
501:                                 stateName -> resourceContainer.getColumnOptions(),
502:                                 parameters.getKvStateRegistry(),
503:                                 parameters.getKeySerializer(),
504:                                 parameters.getNumberOfKeyGroups(),
505:                                 parameters.getKeyGroupRange(),
506:                                 executionConfig,
507:                                 localRecoveryConfig,
508:                                 priorityQueueConfig,
509:                                 parameters.getTtlTimeProvider(),
510:                         metricsTrackingStateConfig,
511:                                 parameters.getMetricGroup(),
512:                                 parameters.getCustomInitializationMetrics(),
513:                                 parameters.getStateHandles(),
514:                                 keyGroupCompressionDecorator,
515:                                 parameters.getCancelStreamRegistry())
516:                         .setEnableIncrementalCheckpointing(isIncrementalCheckpointsEnabled())
517:                         .setNumberOfTransferingThreads(getNumberOfTransferThreads())
518:                         .setNativeMetricOptions(
519:                                 resourceContainer.getMemoryWatcherOptions(nativeMetricOptions))
520:                         .setWriteBatchSize(getWriteBatchSize())
521:                         .setOverlapFractionThreshold(getOverlapFractionThreshold())
522:                         .setIncrementalRestoreAsyncCompactAfterRescale(
523:                                 getIncrementalRestoreAsyncCompactAfterRescale())
524:                         .setUseIngestDbRestoreMode(getUseIngestDbRestoreMode())
525:                         .setRescalingUseDeleteFilesInRange(isRescalingUseDeleteFilesInRange())
526:                         .setIOExecutor(
527:                                 MdcUtils.scopeToJob(
528:                                         jobId,
529:                                         parameters.getEnv().getIOManager().getExecutorService()))
530:                         .setManualCompactionConfig(
531:                                 manualCompactionConfig == null
532:                                         ? RocksDBManualCompactionConfig.getDefault()
533:                                         : manualCompactionConfig)
534:                         .setAsyncExceptionHandler(
535:                                 (ign, throwable) -> parameters.getEnv().failExternally(throwable));
536:         return builder.build();
537:     }
