869:     private ReadableConfig mergeConfigurableOptions(ReadableConfig base, ReadableConfig onTop) {
870:         if (base == null) {
871:             base = new Configuration();
872:         }
873:         Configuration configuration = new Configuration();
874:         Map<String, String> baseMap = base.toMap();
875:         Map<String, String> onTopMap = onTop.toMap();
876:         for (ConfigOption<?> option : RocksDBConfigurableOptions.CANDIDATE_CONFIGS) {
877:             Optional<?> baseValue = base.getOptional(option);
878:             Optional<?> topValue = onTop.getOptional(option);
879: 
880:             if (topValue.isPresent() || baseValue.isPresent()) {
881:                 Object validValue = topValue.isPresent() ? topValue.get() : baseValue.get();
882:                 RocksDBConfigurableOptions.checkArgumentValid(option, validValue);
883:                 String valueString =
884:                         topValue.isPresent()
885:                                 ? onTopMap.get(option.key())
886:                                 : baseMap.get(option.key());
887:                 configuration.setString(option.key(), valueString);
888:             }
889:         }
890:         return configuration;
891:     }
