330:     @Override
331:     public RocksDBKeyedStateBackend<K> build() throws BackendBuildingException {
332:         RocksDBWriteBatchWrapper writeBatchWrapper = null;
333:         ColumnFamilyHandle defaultColumnFamilyHandle = null;
334:         RocksDBNativeMetricMonitor nativeMetricMonitor = null;
335:         CloseableRegistry cancelRegistryForBackend = new CloseableRegistry();
336:         LinkedHashMap<String, RocksDBKeyedStateBackend.RocksDbKvStateInfo> kvStateInformation =
337:                 new LinkedHashMap<>();
338:         LinkedHashMap<String, HeapPriorityQueueSnapshotRestoreWrapper<?>> registeredPQStates =
339:                 new LinkedHashMap<>();
340:         RocksDB db = null;
341:         RocksDBRestoreOperation restoreOperation = null;
342:         CompletableFuture<Void> asyncCompactAfterRestoreFuture = null;
343: 
344:         RocksDbTtlCompactFiltersManager ttlCompactFiltersManager =
345:                 new RocksDbTtlCompactFiltersManager(
346:                         ttlTimeProvider,
347:                         optionsContainer.getQueryTimeAfterNumEntries(),
348:                         optionsContainer.getPeriodicCompactionTime());
349: 
350:         ResourceGuard rocksDBResourceGuard = new ResourceGuard();
351:         RocksDBSnapshotStrategyBase<K, ?> checkpointStrategy = null;
352:         PriorityQueueSetFactory priorityQueueFactory;
353:         SerializedCompositeKeyBuilder<K> sharedRocksKeyBuilder;
354:         // Number of bytes required to prefix the key groups.
355:         int keyGroupPrefixBytes =
356:                 CompositeKeySerializationUtils.computeRequiredBytesInKeyGroupPrefix(
357:                         numberOfKeyGroups);
358:         RocksDBManualCompactionManager manualCompactionManager;
359: 
360:         try {
361:             // Variables for snapshot strategy when incremental checkpoint is enabled
362:             UUID backendUID = UUID.randomUUID();
363:             SortedMap<Long, Collection<HandleAndLocalPath>> materializedSstFiles = new TreeMap<>();
364:             long lastCompletedCheckpointId = -1L;
365:             if (injectedTestDB != null) {
366:                 db = injectedTestDB;
367:                 defaultColumnFamilyHandle = injectedDefaultColumnFamilyHandle;
368:                 nativeMetricMonitor =
369:                         nativeMetricOptions.isEnabled()
370:                                 ? new RocksDBNativeMetricMonitor(
371:                                         nativeMetricOptions, metricGroup, db, null)
372:                                 : null;
373:             } else {
374:                 prepareDirectories();
375:                 restoreOperation =
376:                         getRocksDBRestoreOperation(
377:                                 keyGroupPrefixBytes,
378:                                 rocksDBResourceGuard,
379:                                 cancelStreamRegistry,
380:                                 cancelRegistryForBackend,
381:                                 kvStateInformation,
382:                                 registeredPQStates,
383:                                 ttlCompactFiltersManager);
384:                 RocksDBRestoreResult restoreResult = restoreOperation.restore();
385:                 db = restoreResult.getDb();
386:                 defaultColumnFamilyHandle = restoreResult.getDefaultColumnFamilyHandle();
387:                 nativeMetricMonitor = restoreResult.getNativeMetricMonitor();
388:                 if (ioExecutor != null) {
389:                     asyncCompactAfterRestoreFuture =
390:                             restoreResult
391:                                     .getAsyncCompactTaskAfterRestore()
392:                                     .map((task) -> CompletableFuture.runAsync(task, ioExecutor))
393:                                     .orElse(null);
394:                 }
395:                 if (restoreOperation instanceof RocksDBIncrementalRestoreOperation) {
396:                     backendUID = restoreResult.getBackendUID();
397:                     materializedSstFiles = restoreResult.getRestoredSstFiles();
398:                     lastCompletedCheckpointId = restoreResult.getLastCompletedCheckpointId();
399:                 }
400:             }
401: 
402:             writeBatchWrapper =
403:                     new RocksDBWriteBatchWrapper(
404:                             db, optionsContainer.getWriteOptions(), writeBatchSize);
405: 
406:             // it is important that we only create the key builder after the restore, and not
407:             // before;
408:             // restore operations may reconfigure the key serializer, so accessing the key
409:             // serializer
410:             // only now we can be certain that the key serializer used in the builder is final.
411:             sharedRocksKeyBuilder =
412:                     new SerializedCompositeKeyBuilder<>(
413:                             keySerializerProvider.currentSchemaSerializer(),
414:                             keyGroupPrefixBytes,
415:                             32);
416:             // init snapshot strategy after db is assured to be initialized
417:             checkpointStrategy =
418:                     initializeSavepointAndCheckpointStrategies(
419:                             rocksDBResourceGuard,
420:                             kvStateInformation,
421:                             keyGroupPrefixBytes,
422:                             db,
423:                             backendUID,
424:                             materializedSstFiles,
425:                             lastCompletedCheckpointId);
426:             // init priority queue factory
427:             manualCompactionManager =
428:                     RocksDBManualCompactionManager.create(db, manualCompactionConfig, ioExecutor);
429:             priorityQueueFactory =
430:                     initPriorityQueueFactory(
431:                             keyGroupPrefixBytes,
432:                             kvStateInformation,
433:                             db,
434:                             writeBatchWrapper,
435:                             nativeMetricMonitor,
436:                             manualCompactionManager);
437:         } catch (Throwable e) {
438:             // Do clean up
439:             List<ColumnFamilyOptions> columnFamilyOptions =
440:                     new ArrayList<>(kvStateInformation.values().size());
441:             IOUtils.closeQuietly(cancelRegistryForBackend);
442:             IOUtils.closeQuietly(writeBatchWrapper);
443:             IOUtils.closeQuietly(rocksDBResourceGuard);
444:             RocksDBOperationUtils.addColumnFamilyOptionsToCloseLater(
445:                     columnFamilyOptions, defaultColumnFamilyHandle);
446:             IOUtils.closeQuietly(defaultColumnFamilyHandle);
447:             IOUtils.closeQuietly(nativeMetricMonitor);
448:             for (RocksDBKeyedStateBackend.RocksDbKvStateInfo kvStateInfo :
449:                     kvStateInformation.values()) {
450:                 RocksDBOperationUtils.addColumnFamilyOptionsToCloseLater(
451:                         columnFamilyOptions, kvStateInfo.columnFamilyHandle);
452:                 IOUtils.closeQuietly(kvStateInfo.columnFamilyHandle);
453:             }
454:             IOUtils.closeQuietly(db);
455:             // it's possible that db has been initialized but later restore steps failed
456:             IOUtils.closeQuietly(restoreOperation);
457:             IOUtils.closeAllQuietly(columnFamilyOptions);
458:             IOUtils.closeQuietly(optionsContainer);
459:             ttlCompactFiltersManager.disposeAndClearRegisteredCompactionFactories();
460:             kvStateInformation.clear();
461:             IOUtils.closeQuietly(checkpointStrategy);
462:             try {
463:                 FileUtils.deleteDirectory(instanceBasePath);
464:             } catch (Exception ex) {
465:                 logger.warn("Failed to delete base path for RocksDB: " + instanceBasePath, ex);
466:             }
467:             // Log and rethrow
468:             if (e instanceof BackendBuildingException) {
469:                 throw (BackendBuildingException) e;
470:             } else {
471:                 String errMsg = "Caught unexpected exception.";
472:                 logger.error(errMsg, e);
473:                 throw new BackendBuildingException(errMsg, e);
474:             }
475:         }
476:         InternalKeyContext<K> keyContext =
477:                 new InternalKeyContextImpl<>(keyGroupRange, numberOfKeyGroups);
478:         logger.info("Finished building RocksDB keyed state-backend at {}.", instanceBasePath);
479:         return new RocksDBKeyedStateBackend<>(
480:                 this.userCodeClassLoader,
481:                 this.instanceBasePath,
482:                 this.optionsContainer,
483:                 columnFamilyOptionsFactory,
484:                 this.kvStateRegistry,
485:                 this.keySerializerProvider.currentSchemaSerializer(),
486:                 this.executionConfig,
487:                 this.ttlTimeProvider,
488:                 metricsTrackingStateConfig,
489:                 db,
490:                 kvStateInformation,
491:                 registeredPQStates,
492:                 keyGroupPrefixBytes,
493:                 cancelRegistryForBackend,
494:                 this.keyGroupCompressionDecorator,
495:                 rocksDBResourceGuard,
496:                 checkpointStrategy,
497:                 writeBatchWrapper,
498:                 defaultColumnFamilyHandle,
499:                 nativeMetricMonitor,
500:                 sharedRocksKeyBuilder,
501:                 priorityQueueFactory,
502:                 ttlCompactFiltersManager,
503:                 keyContext,
504:                 writeBatchSize,
505:                 asyncCompactAfterRestoreFuture,
506:                 manualCompactionManager);
507:     }
