509:     private RocksDBRestoreOperation getRocksDBRestoreOperation(
510:             int keyGroupPrefixBytes,
511:             ResourceGuard rocksDBResourceGuard,
512:             CloseableRegistry cancelStreamRegistryForRestore,
513:             CloseableRegistry cancelRegistryForBackend,
514:             LinkedHashMap<String, RocksDBKeyedStateBackend.RocksDbKvStateInfo> kvStateInformation,
515:             LinkedHashMap<String, HeapPriorityQueueSnapshotRestoreWrapper<?>> registeredPQStates,
516:             RocksDbTtlCompactFiltersManager ttlCompactFiltersManager) {
517:         DBOptions dbOptions = optionsContainer.getDbOptions();
518:         if (CollectionUtil.isEmptyOrAllElementsNull(restoreStateHandles)) {
519:             return new RocksDBNoneRestoreOperation<>(
520:                     kvStateInformation,
521:                     instanceRocksDBPath,
522:                     dbOptions,
523:                     columnFamilyOptionsFactory,
524:                     nativeMetricOptions,
525:                     metricGroup,
526:                     ttlCompactFiltersManager,
527:                     optionsContainer.getWriteBufferManagerCapacity());
528:         }
529:         KeyedStateHandle firstStateHandle = restoreStateHandles.iterator().next();
530:         if (firstStateHandle instanceof IncrementalKeyedStateHandle) {
531:             return new RocksDBIncrementalRestoreOperation<>(
532:                     operatorIdentifier,
533:                     keyGroupRange,
534:                     keyGroupPrefixBytes,
535:                     numberOfTransferingThreads,
536:                     rocksDBResourceGuard,
537:                     cancelStreamRegistryForRestore,
538:                     cancelRegistryForBackend,
539:                     userCodeClassLoader,
540:                     kvStateInformation,
541:                     keySerializerProvider,
542:                     instanceBasePath,
543:                     instanceRocksDBPath,
544:                     dbOptions,
545:                     columnFamilyOptionsFactory,
546:                     nativeMetricOptions,
547:                     metricGroup,
548:                     customInitializationMetrics,
549:                     CollectionUtil.checkedSubTypeCast(
550:                             restoreStateHandles, IncrementalKeyedStateHandle.class),
551:                     ttlCompactFiltersManager,
552:                     writeBatchSize,
553:                     optionsContainer.getWriteBufferManagerCapacity(),
554:                     overlapFractionThreshold,
555:                     useIngestDbRestoreMode,
556:                     incrementalRestoreAsyncCompactAfterRescale,
557:                     rescalingUseDeleteFilesInRange,
558:                     ioExecutor,
559:                     asyncExceptionHandler);
560:         } else if (priorityQueueConfig.getPriorityQueueStateType()
561:                 == EmbeddedRocksDBStateBackend.PriorityQueueStateType.HEAP) {
562:             return new RocksDBHeapTimersFullRestoreOperation<>(
563:                     keyGroupRange,
564:                     numberOfKeyGroups,
565:                     userCodeClassLoader,
566:                     kvStateInformation,
567:                     registeredPQStates,
568:                     createHeapQueueFactory(),
569:                     keySerializerProvider,
570:                     instanceRocksDBPath,
571:                     dbOptions,
572:                     columnFamilyOptionsFactory,
573:                     nativeMetricOptions,
574:                     metricGroup,
575:                     restoreStateHandles,
576:                     ttlCompactFiltersManager,
577:                     writeBatchSize,
578:                     optionsContainer.getWriteBufferManagerCapacity(),
579:                     cancelStreamRegistry);
580:         } else {
581:             return new RocksDBFullRestoreOperation<>(
582:                     keyGroupRange,
583:                     userCodeClassLoader,
584:                     kvStateInformation,
585:                     keySerializerProvider,
586:                     instanceRocksDBPath,
587:                     dbOptions,
588:                     columnFamilyOptionsFactory,
589:                     nativeMetricOptions,
590:                     metricGroup,
591:                     restoreStateHandles,
592:                     ttlCompactFiltersManager,
593:                     writeBatchSize,
594:                     optionsContainer.getWriteBufferManagerCapacity(),
595:                     cancelStreamRegistry);
596:         }
597:     }
