599:     private RocksDBSnapshotStrategyBase<K, ?> initializeSavepointAndCheckpointStrategies(
600:             ResourceGuard rocksDBResourceGuard,
601:             LinkedHashMap<String, RocksDBKeyedStateBackend.RocksDbKvStateInfo> kvStateInformation,
602:             int keyGroupPrefixBytes,
603:             RocksDB db,
604:             UUID backendUID,
605:             SortedMap<Long, Collection<HandleAndLocalPath>> materializedSstFiles,
606:             long lastCompletedCheckpointId) {
607:         RocksDBSnapshotStrategyBase<K, ?> checkpointSnapshotStrategy;
608:         RocksDBStateUploader stateUploader =
609:                 injectRocksDBStateUploader == null
610:                         ? new RocksDBStateUploader(
611:                                 RocksDBStateDataTransferHelper.forThreadNumIfSpecified(
612:                                         numberOfTransferingThreads, ioExecutor))
613:                         : injectRocksDBStateUploader;
614:         if (enableIncrementalCheckpointing) {
615:             checkpointSnapshotStrategy =
616:                     new RocksIncrementalSnapshotStrategy<>(
617:                             db,
618:                             rocksDBResourceGuard,
619:                             keySerializerProvider.currentSchemaSerializer(),
620:                             kvStateInformation,
621:                             keyGroupRange,
622:                             keyGroupPrefixBytes,
623:                             localRecoveryConfig,
624:                             instanceBasePath,
625:                             backendUID,
626:                             materializedSstFiles,
627:                             stateUploader,
628:                             lastCompletedCheckpointId);
629:         } else {
630:             checkpointSnapshotStrategy =
631:                     new RocksNativeFullSnapshotStrategy<>(
632:                             db,
633:                             rocksDBResourceGuard,
634:                             keySerializerProvider.currentSchemaSerializer(),
635:                             kvStateInformation,
636:                             keyGroupRange,
637:                             keyGroupPrefixBytes,
638:                             localRecoveryConfig,
639:                             instanceBasePath,
640:                             backendUID,
641:                             stateUploader);
642:         }
643:         return checkpointSnapshotStrategy;
644:     }
