646:     private PriorityQueueSetFactory initPriorityQueueFactory(
647:             int keyGroupPrefixBytes,
648:             Map<String, RocksDBKeyedStateBackend.RocksDbKvStateInfo> kvStateInformation,
649:             RocksDB db,
650:             RocksDBWriteBatchWrapper writeBatchWrapper,
651:             RocksDBNativeMetricMonitor nativeMetricMonitor,
652:             RocksDBManualCompactionManager manualCompactionManager) {
653:         PriorityQueueSetFactory priorityQueueFactory;
654:         switch (priorityQueueConfig.getPriorityQueueStateType()) {
655:             case HEAP:
656:                 priorityQueueFactory = createHeapQueueFactory();
657:                 break;
658:             case ROCKSDB:
659:                 priorityQueueFactory =
660:                         new RocksDBPriorityQueueSetFactory(
661:                                 keyGroupRange,
662:                                 keyGroupPrefixBytes,
663:                                 numberOfKeyGroups,
664:                                 kvStateInformation,
665:                                 db,
666:                                 optionsContainer.getReadOptions(),
667:                                 writeBatchWrapper,
668:                                 nativeMetricMonitor,
669:                                 columnFamilyOptionsFactory,
670:                                 optionsContainer.getWriteBufferManagerCapacity(),
671:                                 priorityQueueConfig.getRocksDBPriorityQueueSetCacheSize(),
672:                                 manualCompactionManager);
673:                 break;
674:             default:
675:                 throw new IllegalArgumentException(
676:                         "Unknown priority queue state type: "
677:                                 + priorityQueueConfig.getPriorityQueueStateType());
678:         }
679:         return priorityQueueFactory;
680:     }
