1251:     /**
1252:      * In this weird construct, we are:
1253:      *
1254:      * <ul>
1255:      *   <li>1. We start a thread, which will...
1256:      *   <li>2. ... sleep for X ms, and enqueue another mail, that will...
1257:      *   <li>3. ... sleep for Y ms, and make the output available again
1258:      * </ul>
1259:      *
1260:      * <p>2nd step is to check that back pressure or idle counter is at least X. In the last 3rd
1261:      * step, we test whether this counter was paused for the duration of processing mails.
1262:      */
1263:     private static class WaitingThread extends Thread {
1264:         private final MailboxExecutor executor;
1265:         private final RunnableWithException resumeTask;
1266:         private final long sleepTimeInsideMail;
1267:         private final long sleepTimeOutsideMail;
1268:         private final TimerGauge sleepOutsideMailTimer;
1269: 
1270:         @Nullable private Exception asyncException;
1271: 
1272:         public WaitingThread(
1273:                 MailboxExecutor executor,
1274:                 RunnableWithException resumeTask,
1275:                 long sleepTimeInsideMail,
1276:                 long sleepTimeOutsideMail,
1277:                 TimerGauge sleepOutsideMailTimer) {
1278:             this.executor = executor;
1279:             this.resumeTask = resumeTask;
1280:             this.sleepTimeInsideMail = sleepTimeInsideMail;
1281:             this.sleepTimeOutsideMail = sleepTimeOutsideMail;
1282:             this.sleepOutsideMailTimer = sleepOutsideMailTimer;
1283:         }
1284: 
1285:         @Override
1286:         public void run() {
1287:             try {
1288:                 // Make sure that the Task thread actually starts measuring the backpressure before
1289:                 // we start the measured sleep. The WaitingThread is started from within the mailbox
1290:                 // so we should first wait until mailbox loop starts idling before we enter the
1291:                 // measured sleep
1292:                 while (!sleepOutsideMailTimer.isMeasuring()) {
1293:                     Thread.sleep(1);
1294:                 }
1295:                 Thread.sleep(sleepTimeOutsideMail);
1296:             } catch (InterruptedException e) {
1297:                 asyncException = e;
1298:             }
1299:             executor.execute(
1300:                     () -> {
1301:                         if (asyncException != null) {
1302:                             throw asyncException;
1303:                         }
1304:                         Thread.sleep(sleepTimeInsideMail);
1305:                         resumeTask.run();
1306:                     },
1307:                     "This task will complete the future to resume process input action.");
1308:         }
1309:     }
