1953:     private static class RunningTask<T extends StreamTask<?, ?>> {
1954:         final T streamTask;
1955:         final CompletableFuture<Void> invocationFuture;
1956: 
1957:         RunningTask(T streamTask, CompletableFuture<Void> invocationFuture) {
1958:             this.streamTask = streamTask;
1959:             this.invocationFuture = invocationFuture;
1960:         }
1961: 
1962:         void waitForTaskCompletion(boolean cancelled) throws Exception {
1963:             try {
1964:                 invocationFuture.get();
1965:             } catch (Exception e) {
1966:                 if (cancelled) {
1967:                     assertThat(e).hasCauseInstanceOf(CancelTaskException.class);
1968:                 } else {
1969:                     throw e;
1970:                 }
1971:             }
1972:             assertThat(streamTask.isCanceled()).isEqualTo(cancelled);
1973:         }
1974:     }
1975: 
1976:     private static <T extends StreamTask<?, ?>> RunningTask<T> runTask(
1977:             SupplierWithException<T, Exception> taskFactory) throws Exception {
1978:         CompletableFuture<T> taskCreationFuture = new CompletableFuture<>();
1979:         CompletableFuture<Void> invocationFuture =
1980:                 CompletableFuture.runAsync(
1981:                         () -> {
1982:                             T task;
1983:                             try {
1984:                                 task = taskFactory.get();
1985:                                 taskCreationFuture.complete(task);
1986:                             } catch (Exception e) {
1987:                                 taskCreationFuture.completeExceptionally(e);
1988:                                 return;
1989:                             }
1990:                             try {
1991:                                 task.invoke();
1992:                             } catch (RuntimeException e) {
1993:                                 throw e;
1994:                             } catch (Exception e) {
1995:                                 throw new RuntimeException(e);
1996:                             }
1997:                         },
1998:                         Executors.newSingleThreadExecutor());
1999: 
2000:         // Wait until task is created.
2001:         return new RunningTask<>(taskCreationFuture.get(), invocationFuture);
2002:     }
