2624:     private static final class BlockingRunnableFuture<V> implements RunnableFuture<V> {
2625: 
2626:         private final CompletableFuture<V> future = new CompletableFuture<>();
2627: 
2628:         private final OneShotLatch signalRunLatch = new OneShotLatch();
2629: 
2630:         private final CountDownLatch continueRunLatch;
2631: 
2632:         private final V value;
2633: 
2634:         private BlockingRunnableFuture(int parties, V value) {
2635:             this.continueRunLatch = new CountDownLatch(parties);
2636:             this.value = value;
2637:         }
2638: 
2639:         @Override
2640:         public void run() {
2641:             signalRunLatch.trigger();
2642:             continueRunLatch.countDown();
2643: 
2644:             try {
2645:                 // poor man's barrier because it can happen that the async operations thread gets
2646:                 // interrupted by the mail box thread. The CyclicBarrier would in this case fail
2647:                 // all participants of the barrier, leaving the future uncompleted
2648:                 continueRunLatch.await();
2649:             } catch (InterruptedException e) {
2650:                 ExceptionUtils.rethrow(e);
2651:             }
2652: 
2653:             future.complete(value);
2654:         }
2655: 
2656:         @Override
2657:         public boolean cancel(boolean mayInterruptIfRunning) {
2658:             return false;
2659:         }
2660: 
2661:         @Override
2662:         public boolean isCancelled() {
2663:             return future.isCancelled();
2664:         }
2665: 
2666:         @Override
2667:         public boolean isDone() {
2668:             return future.isDone();
2669:         }
2670: 
2671:         @Override
2672:         public V get() throws InterruptedException, ExecutionException {
2673:             return future.get();
2674:         }
2675: 
2676:         @Override
2677:         public V get(long timeout, TimeUnit unit)
2678:                 throws InterruptedException, ExecutionException, TimeoutException {
2679:             return future.get(timeout, unit);
2680:         }
2681: 
2682:         void awaitRun() throws InterruptedException {
2683:             signalRunLatch.await();
2684:         }
