364:     public <N, S extends State> S getPartitionedState(
365:             N namespace,
366:             TypeSerializer<N> namespaceSerializer,
367:             StateDescriptor<S, ?> stateDescriptor)
368:             throws Exception {
369: 
370:         checkNotNull(namespace, "Namespace");
371: 
372:         if (lastName != null && lastName.equals(stateDescriptor.getName())) {
373:             lastState.setCurrentNamespace(namespace);
374:             return (S) lastState;
375:         }
376: 
377:         final InternalKvState<K, ?, ?> previous =
378:                 keyValueStatesByName.get(stateDescriptor.getName());
379:         if (previous != null) {
380:             lastState = previous;
381:             lastState.setCurrentNamespace(namespace);
382:             lastName = stateDescriptor.getName();
383:             functionDelegationHelper.addOrUpdate(stateDescriptor);
384:             return (S) previous;
385:         }
386: 
387:         final S state = getOrCreateKeyedState(namespaceSerializer, stateDescriptor);
388:         final InternalKvState<K, N, ?> kvState = (InternalKvState<K, N, ?>) state;
389: 
390:         lastName = stateDescriptor.getName();
391:         lastState = kvState;
392:         kvState.setCurrentNamespace(namespace);
393: 
394:         return state;
395:     }
