397:     @Nonnull
398:     @Override
399:     public RunnableFuture<SnapshotResult<KeyedStateHandle>> snapshot(
400:             long checkpointId,
401:             long timestamp,
402:             @Nonnull CheckpointStreamFactory streamFactory,
403:             @Nonnull CheckpointOptions checkpointOptions)
404:             throws Exception {
405: 
406:         if (checkpointOptions.getCheckpointType().isSavepoint()) {
407:             return nativeSavepoint(checkpointId, timestamp, streamFactory, checkpointOptions);
408:         }
409: 
410:         // The range to upload may overlap with the previous one(s). To reuse them, we could store
411:         // the previous results either here in the backend or in the writer. However,
412:         // materialization may truncate only a part of the previous result and the backend would
413:         // have to split it somehow for the former option, so the latter is used.
414:         lastCheckpointId = checkpointId;
415:         lastUploadedFrom = changelogSnapshotState.lastMaterializedTo();
416:         lastUploadedTo = stateChangelogWriter.nextSequenceNumber();
417:         changelogTruncateHelper.checkpoint(checkpointId, lastUploadedTo);
418: 
419:         LOG.info(
420:                 "snapshot of {} for checkpoint {}, change range: {}..{}, materialization ID {}",
421:                 subtaskName,
422:                 checkpointId,
423:                 lastUploadedFrom,
424:                 lastUploadedTo,
425:                 changelogSnapshotState.getMaterializationID());
426: 
427:         ChangelogSnapshotState changelogStateBackendStateCopy = changelogSnapshotState;
428: 
429:         materializationIdByCheckpointId.put(
430:                 checkpointId, changelogStateBackendStateCopy.materializationID);
431: 
432:         return toRunnableFuture(
433:                 stateChangelogWriter
434:                         .persist(lastUploadedFrom, checkpointId)
435:                         .thenApply(
436:                                 delta ->
437:                                         buildSnapshotResult(
438:                                                 checkpointId,
439:                                                 delta,
440:                                                 changelogStateBackendStateCopy))
441:                         .whenComplete(
442:                                 (snapshotResult, throwable) ->
443:                                         metrics.reportSnapshotResult(snapshotResult))
444:                         .thenApply(this::castSnapshotResult));
445:     }
446: 
447:     private RunnableFuture<SnapshotResult<KeyedStateHandle>> nativeSavepoint(
448:             long checkpointId,
449:             long timestamp,
450:             @Nonnull CheckpointStreamFactory streamFactory,
451:             @Nonnull CheckpointOptions checkpointOptions)
452:             throws Exception {
453: 
454:         SnapshotType.SharingFilesStrategy sharingFilesStrategy =
455:                 checkpointOptions.getCheckpointType().getSharingFilesStrategy();
456:         if (sharingFilesStrategy != SnapshotType.SharingFilesStrategy.NO_SHARING) {
457:             throw new UnsupportedOperationException(
458:                     "ChangelogKeyedStateBackend doesn't support native savepoint with SharingFilesStrategy: "
459:                             + sharingFilesStrategy);
460:         }
461: 
462:         long materializationID = materializedId++;
463:         // For NO_SHARING native savepoint, trigger delegated one
464:         RunnableFuture<SnapshotResult<KeyedStateHandle>> delegatedSnapshotResult =
465:                 keyedStateBackend.snapshot(
466:                         materializationID, timestamp, streamFactory, checkpointOptions);
467: 
468:         materializationIdByCheckpointId.put(checkpointId, materializationID);
469:         return new FutureTask<SnapshotResult<KeyedStateHandle>>(
470:                 () -> {
471:                     SnapshotResult<KeyedStateHandle> result =
472:                             FutureUtils.runIfNotDoneAndGet(delegatedSnapshotResult);
473:                     return castSnapshotResult(
474:                             buildSnapshotResult(
475:                                     checkpointId,
476:                                     SnapshotResult.empty(),
477:                                     new ChangelogSnapshotState(
478:                                             getMaterializedResult(result), materializationID)));
479:                 }) {
480:             @Override
481:             public boolean cancel(boolean mayInterruptIfRunning) {
482:                 return delegatedSnapshotResult.cancel(mayInterruptIfRunning)
483:                         && super.cancel(mayInterruptIfRunning);
484:             }
485: 
486:             @Override
487:             public boolean isCancelled() {
488:                 return delegatedSnapshotResult.isCancelled() && super.isCancelled();
489:             }
490: 
491:             @Override
492:             public boolean isDone() {
493:                 return delegatedSnapshotResult.isDone() && super.isDone();
494:             }
495:         };
496:     }
