632:     // -------------------- CheckpointListener --------------------------------
633:     @Override
634:     public void notifyCheckpointComplete(long checkpointId) throws Exception {
635:         if (lastCheckpointId == checkpointId) {
636:             // Notify the writer so that it can re-use the previous uploads. Do NOT notify it about
637:             // a range status change if it is not relevant anymore. Otherwise, it could CONFIRM a
638:             // newer upload instead of the previous one. This newer upload could then be re-used
639:             // while in fact JM has discarded its results.
640:             // This might change if the log ownership changes (the method won't likely be needed).
641:             stateChangelogWriter.confirm(lastUploadedFrom, lastUploadedTo, checkpointId);
642:         }
643:         Long materializationID = materializationIdByCheckpointId.remove(checkpointId);
644:         if (materializationID != null) {
645:             if (materializationID > lastConfirmedMaterializationId) {
646:                 keyedStateBackend.notifyCheckpointComplete(materializationID);
647:                 lastConfirmedMaterializationId = materializationID;
648:             }
649:         }
650:         materializationIdByCheckpointId.headMap(checkpointId, true).clear();
651:     }
652: 
653:     @Override
654:     public void notifyCheckpointAborted(long checkpointId) throws Exception {
655:         if (lastCheckpointId == checkpointId) {
656:             // Notify the writer so that it can clean up. Do NOT notify it about a range status
657:             // change if it is not relevant anymore. Otherwise, it could DISCARD a newer upload
658:             // instead of the previous one. Rely on truncation for the cleanup in this case.
659:             // This might change if the log ownership changes (the method won't likely be needed).
660:             stateChangelogWriter.reset(lastUploadedFrom, lastUploadedTo, checkpointId);
661:         }
662:         // TODO: Consider notifying nested state backend about checkpoint abortion (FLINK-25850)
663:     }
