62:                     throws Exception {
63:         if (latencyTrackingStateConfig.isEnabled()) {
64:             return new MetricsTrackingStateFactory<>(
65:                             kvState, stateDescriptor, latencyTrackingStateConfig)
66:                     .createState();
67:         }
68:         return kvState;
69:     }
