92:     private IS createState() throws Exception {
93:         SupplierWithException<IS, Exception> stateFactory =
94:                 stateFactories.get(stateDescriptor.getType());
95:         if (stateFactory == null) {
96:             String message =
97:                     String.format(
98:                             "State %s is not supported by %s",
99:                             stateDescriptor.getClass(), MetricsTrackingStateFactory.class);
100:             throw new FlinkRuntimeException(message);
101:         }
102:         return stateFactory.get();
103:     }
