389:                 || !(columnInfo.metaInfo instanceof RegisteredKeyValueStateBackendMetaInfo)) {
390:             return Stream.empty();
391:         }
392: 
393:         @SuppressWarnings("unchecked")
394:         RegisteredKeyValueStateBackendMetaInfo<N, ?> registeredKeyValueStateBackendMetaInfo =
395:                 (RegisteredKeyValueStateBackendMetaInfo<N, ?>) columnInfo.metaInfo;
396: 
397:         final TypeSerializer<N> namespaceSerializer =
398:                 registeredKeyValueStateBackendMetaInfo.getNamespaceSerializer();
399:         boolean ambiguousKeyPossible =
400:                 CompositeKeySerializationUtils.isAmbiguousKeyPossible(
401:                         getKeySerializer(), namespaceSerializer);
402: 
403:         ForStIteratorWrapper iterator =
404:                 ForStOperationUtils.getForStIterator(
405:                         db, columnInfo.columnFamilyHandle, readOptions);
406:         iterator.seekToFirst();
407: 
408:         final ForStStateKeysAndNamespaceIterator<K, N> iteratorWrapper =
409:                 new ForStStateKeysAndNamespaceIterator<>(
410:                         iterator,
411:                         state,
412:                         getKeySerializer(),
413:                         namespaceSerializer,
414:                         keyGroupPrefixBytes,
415:                         ambiguousKeyPossible);
416: 
417:         Stream<Tuple2<K, N>> targetStream =
418:                 StreamSupport.stream(
419:                         Spliterators.spliteratorUnknownSize(iteratorWrapper, Spliterator.ORDERED),
420:                         false);
421:         return targetStream.onClose(iteratorWrapper::close);
422:     }
