436:     /** Should only be called by one thread, and only after all accesses to the DB happened. */
437:     @Override
438:     public void dispose() {
439:         if (this.disposed) {
440:             return;
441:         }
442:         super.dispose();
443: 
444:         // This call will block until all clients that still acquire access to the ForSt instance
445:         // have released it,
446:         // so that we cannot release the native resources while clients are still working with it in
447:         // parallel.
448:         forstResourceGuard.close();
449: 
450:         // IMPORTANT: null reference to signal potential async checkpoint workers that the db was
451:         // disposed, as
452:         // working on the disposed object results in SEGFAULTS.
453:         if (db != null) {
454:             IOUtils.closeQuietly(writeBatchWrapper);
455: 
456:             // Metric collection occurs on a background thread. When this method returns
457:             // it is guaranteed that thr ForSt reference has been invalidated
458:             // and no more metric collection will be attempted against the database.
459:             if (nativeMetricMonitor != null) {
460:                 nativeMetricMonitor.close();
461:             }
462: 
463:             List<ColumnFamilyOptions> columnFamilyOptions =
464:                     new ArrayList<>(kvStateInformation.values().size());
465: 
466:             // RocksDB's native memory management requires that *all* CFs (including default) are
467:             // closed before the
468:             // DB is closed. See:
469:             // https://github.com/facebook/rocksdb/wiki/RocksJava-Basics#opening-a-database-with-column-families
470:             // Start with default CF ...
471:             ForStOperationUtils.addColumnFamilyOptionsToCloseLater(
472:                     columnFamilyOptions, defaultColumnFamily);
473:             IOUtils.closeQuietly(defaultColumnFamily);
474: 
475:             // ... continue with the ones created by Flink...
476:             for (ForStOperationUtils.ForStKvStateInfo kvStateInfo : kvStateInformation.values()) {
477:                 ForStOperationUtils.addColumnFamilyOptionsToCloseLater(
478:                         columnFamilyOptions, kvStateInfo.columnFamilyHandle);
479:                 IOUtils.closeQuietly(kvStateInfo.columnFamilyHandle);
480:             }
481: 
482:             // ... and finally close the DB instance ...
483:             IOUtils.closeQuietly(db);
484: 
485:             columnFamilyOptions.forEach(IOUtils::closeQuietly);
486: 
487:             LOG.info(
488:                     "Closed ForSt State Backend. Cleaning up ForSt local working directory {}, remote working directory {}.",
489:                     optionsContainer.getLocalBasePath(),
490:                     optionsContainer.getRemoteBasePath());
491: 
492:             try {
493:                 optionsContainer.clearDirectories();
494:             } catch (Exception ex) {
495:                 LOG.warn(
496:                         "Could not delete ForSt local working directory {}, remote working directory {}.",
497:                         optionsContainer.getLocalBasePath(),
498:                         optionsContainer.getRemoteBasePath(),
499:                         ex);
500:             }
501: 
502:             IOUtils.closeQuietly(optionsContainer);
503: 
504:             kvStateInformation.clear();
505:         }
506:         IOUtils.closeQuietly(checkpointSnapshotStrategy);
507:         this.disposed = true;
508:     }
