574:             final long checkpointId,
575:             final long timestamp,
576:             @Nonnull final CheckpointStreamFactory streamFactory,
577:             @Nonnull CheckpointOptions checkpointOptions)
578:             throws Exception {
579: 
580:         // flush everything into db before taking a snapshot
