612:     /**
613:      * Registers a k/v state information, which includes its state id, type, ForSt column family
614:      * handle, and serializers.
615:      *
616:      * <p>When restoring from a snapshot, we don’t restore the individual k/v states, just the
617:      * global ForSt database and the list of k/v state information. When a k/v state is first
618:      * requested we check here whether we already have a registered entry for that and return it
619:      * (after some necessary state compatibility checks) or create a new one if it does not exist.
620:      */
621:     private <N, S extends State, SV, SEV>
622:             Tuple2<ColumnFamilyHandle, RegisteredKeyValueStateBackendMetaInfo<N, SV>>
623:                     tryRegisterKvStateInformation(
624:                             StateDescriptor<S, SV> stateDesc,
625:                             TypeSerializer<N> namespaceSerializer,
626:                             @Nonnull StateSnapshotTransformFactory<SEV> snapshotTransformFactory,
627:                             boolean allowFutureMetadataUpdates)
628:                             throws Exception {
629: 
630:         ForStOperationUtils.ForStKvStateInfo oldStateInfo =
631:                 kvStateInformation.get(stateDesc.getName());
632: 
633:         TypeSerializer<SV> stateSerializer = stateDesc.getSerializer();
634: 
635:         ForStOperationUtils.ForStKvStateInfo newRocksStateInfo;
636:         RegisteredKeyValueStateBackendMetaInfo<N, SV> newMetaInfo;
637:         if (oldStateInfo != null) {
638:             @SuppressWarnings("unchecked")
639:             RegisteredKeyValueStateBackendMetaInfo<N, SV> castedMetaInfo =
640:                     (RegisteredKeyValueStateBackendMetaInfo<N, SV>) oldStateInfo.metaInfo;
641: 
642:             newMetaInfo =
643:                     updateRestoredStateMetaInfo(
644:                             Tuple2.of(oldStateInfo.columnFamilyHandle, castedMetaInfo),
645:                             stateDesc,
646:                             namespaceSerializer,
647:                             stateSerializer);
648: 
649:             newMetaInfo =
650:                     allowFutureMetadataUpdates
651:                             ? newMetaInfo.withSerializerUpgradesAllowed()
652:                             : newMetaInfo;
653: 
654:             newRocksStateInfo =
655:                     new ForStOperationUtils.ForStKvStateInfo(
656:                             oldStateInfo.columnFamilyHandle, newMetaInfo);
657:             kvStateInformation.put(stateDesc.getName(), newRocksStateInfo);
658:         } else {
659:             newMetaInfo =
660:                     new RegisteredKeyValueStateBackendMetaInfo<>(
661:                             stateDesc.getType(),
662:                             stateDesc.getName(),
663:                             namespaceSerializer,
664:                             stateSerializer,
665:                             StateSnapshotTransformFactory.noTransform());
666: 
667:             newMetaInfo =
668:                     allowFutureMetadataUpdates
669:                             ? newMetaInfo.withSerializerUpgradesAllowed()
670:                             : newMetaInfo;
671: 
672:             newRocksStateInfo =
673:                     ForStOperationUtils.createStateInfo(
674:                             newMetaInfo,
675:                             db,
676:                             columnFamilyOptionsFactory,
677:                             ttlCompactFiltersManager,
678:                             optionsContainer.getWriteBufferManagerCapacity(),
679:                             // Using ICloseableRegistry.NO_OP here because there is no restore in
680:                             // progress; created column families will be closed in dispose()
681:                             ICloseableRegistry.NO_OP);
682:             ForStOperationUtils.registerKvStateInformation(
683:                     this.kvStateInformation,
684:                     this.nativeMetricMonitor,
685:                     stateDesc.getName(),
686:                     newRocksStateInfo);
687:         }
688: 
689:         // todo: update SnapshotTransformFactory
690:         return Tuple2.of(newRocksStateInfo.columnFamilyHandle, newMetaInfo);
691:     }
