693:     private <N, S extends State, SV>
694:             RegisteredKeyValueStateBackendMetaInfo<N, SV> updateRestoredStateMetaInfo(
695:                     Tuple2<ColumnFamilyHandle, RegisteredKeyValueStateBackendMetaInfo<N, SV>>
696:                             oldStateInfo,
697:                     StateDescriptor<S, SV> stateDesc,
698:                     TypeSerializer<N> namespaceSerializer,
699:                     TypeSerializer<SV> stateSerializer)
700:                     throws Exception {
701: 
702:         RegisteredKeyValueStateBackendMetaInfo<N, SV> restoredKvStateMetaInfo = oldStateInfo.f1;
703: 
704:         // fetch current serializer now because if it is incompatible, we can't access
705:         // it anymore to improve the error message
706:         TypeSerializer<N> previousNamespaceSerializer =
707:                 restoredKvStateMetaInfo.getNamespaceSerializer();
708: 
709:         TypeSerializerSchemaCompatibility<N> s =
710:                 restoredKvStateMetaInfo.updateNamespaceSerializer(namespaceSerializer);
711:         if (s.isCompatibleAfterMigration() || s.isIncompatible()) {
712:             throw new StateMigrationException(
713:                     "The new namespace serializer ("
714:                             + namespaceSerializer
715:                             + ") must be compatible with the old namespace serializer ("
716:                             + previousNamespaceSerializer
717:                             + ").");
718:         }
719: 
720:         restoredKvStateMetaInfo.checkStateMetaInfo(stateDesc);
721: 
722:         // fetch current serializer now because if it is incompatible, we can't access
723:         // it anymore to improve the error message
724:         TypeSerializer<SV> previousStateSerializer = restoredKvStateMetaInfo.getStateSerializer();
725: 
726:         TypeSerializerSchemaCompatibility<SV> newStateSerializerCompatibility =
727:                 restoredKvStateMetaInfo.updateStateSerializer(stateSerializer);
728:         if (newStateSerializerCompatibility.isCompatibleAfterMigration()) {
729:             migrateStateValues(stateDesc, oldStateInfo);
730:         } else if (newStateSerializerCompatibility.isIncompatible()) {
731:             throw new StateMigrationException(
732:                     "The new state serializer ("
733:                             + stateSerializer
734:                             + ") must not be incompatible with the old state serializer ("
735:                             + previousStateSerializer
736:                             + ").");
737:         }
738: 
739:         return restoredKvStateMetaInfo;
740:     }
