226:     /** An invokable that doesn't do anything interesting, but does support checkpointing. */
227:     public static class CheckpointingNoOpInvokable extends AbstractInvokable {
228: 
229:         private static final long CANCEL_SIGNAL = -2L;
230:         private final BlockingQueue<Long> checkpointsToConfirm = new ArrayBlockingQueue<>(1);
231: 
232:         public CheckpointingNoOpInvokable(Environment environment) {
233:             super(environment);
234:         }
235: 
236:         @Override
237:         public void invoke() throws Exception {
238:             long signal = checkpointsToConfirm.take();
239:             while (signal != CANCEL_SIGNAL) {
240:                 getEnvironment().acknowledgeCheckpoint(signal, new CheckpointMetrics());
241:                 signal = checkpointsToConfirm.take();
242:             }
243:         }
244: 
245:         @Override
246:         public void cancel() throws Exception {
247:             checkpointsToConfirm.add(CANCEL_SIGNAL);
248:         }
249: 
250:         @Override
251:         public CompletableFuture<Boolean> triggerCheckpointAsync(
252:                 CheckpointMetaData checkpointMetaData, CheckpointOptions checkpointOptions) {
253:             checkpointsToConfirm.add(checkpointMetaData.getCheckpointId());
254:             return CompletableFuture.completedFuture(true);
255:         }
256: 
257:         @Override
258:         public Future<Void> notifyCheckpointCompleteAsync(long checkpointId) {
259:             return CompletableFuture.completedFuture(null);
260:         }
261: 
262:         @Override
263:         public Future<Void> notifyCheckpointSubsumedAsync(long checkpointId) {
264:             return CompletableFuture.completedFuture(null);
265:         }
266:     }
267: 
268:     private StreamGraph createBlockingStreamGraph(int parallelism) throws IOException {
269:         final JobVertex blockingOperator = new JobVertex("Blocking operator", JOB_VERTEX_ID);
270: 
271:         blockingOperator.setInvokableClass(OnceBlockingNoOpInvokable.class);
272: 
273:         blockingOperator.setParallelism(parallelism);
274: 
275:         final StreamGraph jobGraph = JobGraphTestUtils.streamingJobGraph(blockingOperator);
276: 
277:         RestartStrategyUtils.configureFixedDelayRestartStrategy(jobGraph, 1, 0L);
278: 
279:         return jobGraph;
280:     }
281: 
282:     private void waitUntilParallelismForVertexReached(
283:             JobID jobId, JobVertexID jobVertexId, int targetParallelism) throws Exception {
284: 
285:         CommonTestUtils.waitUntilCondition(
286:                 () -> {
287:                     final ArchivedExecutionGraph archivedExecutionGraph =
288:                             internalMiniClusterExtension
289:                                     .getMiniCluster()
290:                                     .getArchivedExecutionGraph(jobId)
291:                                     .get();
292: 
293:                     final AccessExecutionJobVertex executionJobVertex =
294:                             archivedExecutionGraph.getAllVertices().get(jobVertexId);
295: 
296:                     if (executionJobVertex == null) {
297:                         // parallelism was not yet determined
298:                         return false;
299:                     }
300: 
301:                     return executionJobVertex.getParallelism() == targetParallelism;
302:                 });
303:     }
304: }
