322:         // JobVertexBuildContext only contains incrementally generated jobVertex instances. The
323:         // setName method needs to set the names based on the topological order of all jobVertices,
324:         // so it relies on the job graph to compute a difference set.
325:         jobVertexBuildContext
326:                 .getJobGraph()
327:                 .getVerticesSortedTopologicallyFromSources()
328:                 .forEach(
329:                         vertex -> {
330:                             if (jobVertexIds.contains(vertex.getID())) {
331:                                 vertex.setName(
332:                                         String.format(
333:                                                 "[vertex-%d]%s",
334:                                                 vertexIndexId.getAndIncrement(), vertex.getName()));
335:                             }
336:                         });
337:     }
