364:     private static void buildCascadingDescription(
365:             StringBuilder builder,
366:             int headOpId,
367:             int currentOpId,
368:             JobVertexBuildContext jobVertexBuildContext) {
369:         StreamNode node = jobVertexBuildContext.getStreamGraph().getStreamNode(currentOpId);
370:         builder.append(getDescriptionWithChainedSourcesInfo(node, jobVertexBuildContext));
371: 
372:         LinkedList<Integer> chainedOutput =
373:                 getChainedOutputNodes(headOpId, node, jobVertexBuildContext);
374:         if (chainedOutput.isEmpty()) {
375:             return;
376:         }
377:         builder.append(" -> ");
378: 
379:         boolean multiOutput = chainedOutput.size() > 1;
380:         if (multiOutput) {
381:             builder.append("(");
382:         }
383:         while (true) {
384:             Integer outputId = chainedOutput.pollFirst();
385:             buildCascadingDescription(builder, headOpId, outputId, jobVertexBuildContext);
386:             if (chainedOutput.isEmpty()) {
387:                 break;
388:             }
389:             builder.append(" , ");
390:         }
391:         if (multiOutput) {
392:             builder.append(")");
393:         }
394:     }
