492:     @SuppressWarnings("deprecation")
493:     public static void preValidate(org.apache.flink.streaming.api.graph.StreamGraph streamGraph, ClassLoader userClassloader) {
494:         CheckpointConfig checkpointConfig = streamGraph.getCheckpointConfig();
495: 
496:         if (checkpointConfig.isCheckpointingEnabled()) {
497:             // temporarily forbid checkpointing for iterative jobs
498:             if (streamGraph.isIterative()
499:                     && checkpointConfig.isUnalignedCheckpointsEnabled()
500:                     && !checkpointConfig.isForceUnalignedCheckpoints()) {
501:                 throw new UnsupportedOperationException(
502:                         "Unaligned Checkpoints are currently not supported for iterative jobs, "
503:                                 + "as rescaling would require alignment (in addition to the reduced checkpointing guarantees)."
504:                                 + "\nThe user can force Unaligned Checkpoints by using 'execution.checkpointing.unaligned.forced'");
505:             }
506:             if (checkpointConfig.isUnalignedCheckpointsEnabled()
507:                     && !checkpointConfig.isForceUnalignedCheckpoints()
508:                     && streamGraph.getStreamNodes().stream()
509:                             .anyMatch(StreamingJobGraphGenerator::hasCustomPartitioner)) {
510:                 throw new UnsupportedOperationException(
511:                         "Unaligned checkpoints are currently not supported for custom partitioners, "
512:                                 + "as rescaling is not guaranteed to work correctly."
513:                                 + "\nThe user can force Unaligned Checkpoints by using 'execution.checkpointing.unaligned.forced'");
514:             }
515: 
516:             for (StreamNode node : streamGraph.getStreamNodes()) {
517:                 StreamOperatorFactory operatorFactory = node.getOperatorFactory();
518:                 if (operatorFactory != null) {
519:                     Class<?> operatorClass =
520:                             operatorFactory.getStreamOperatorClass(userClassloader);
521:                     if (InputSelectable.class.isAssignableFrom(operatorClass)) {
522: 
523:                         throw new UnsupportedOperationException(
524:                                 "Checkpointing is currently not supported for operators that implement InputSelectable:"
525:                                         + operatorClass.getName());
526:                     }
527:                 }
528:             }
529:         }
530: 
531:         if (checkpointConfig.isUnalignedCheckpointsEnabled()
532:                 && streamGraph.getCheckpointingMode() != CheckpointingMode.EXACTLY_ONCE) {
533:             LOG.warn("Unaligned checkpoints can only be used with checkpointing mode EXACTLY_ONCE");
534:             checkpointConfig.enableUnalignedCheckpoints(false);
535:         }
536:     }
