583:     /**
584:      * Sets up task chains from the source {@link StreamNode} instances.
585:      *
586:      * <p>This will recursively create all {@link JobVertex} instances.
587:      */
588:     private void setChaining() {
589:         // we separate out the sources that run as inputs to another operator (chained inputs)
590:         // from the sources that needs to run as the main (head) operator.
591:         final Map<Integer, OperatorChainInfo> chainEntryPoints =
592:                 buildChainedInputsAndGetHeadInputs();
593:         final Collection<OperatorChainInfo> initialEntryPoints =
594:                 chainEntryPoints.entrySet().stream()
595:                         .sorted(Comparator.comparing(Map.Entry::getKey))
596:                         .map(Map.Entry::getValue)
597:                         .collect(Collectors.toList());
598: 
599:         // iterate over a copy of the values, because this map gets concurrently modified
600:         for (OperatorChainInfo info : initialEntryPoints) {
601:             createChain(
602:                     info.getStartNodeId(),
603:                     1, // operators start at position 1 because 0 is for chained source inputs
604:                     info,
605:                     chainEntryPoints,
606:                     true,
607:                     serializationExecutor,
608:                     jobVertexBuildContext,
609:                     null);
610:         }
611:     }
