894:     public static StreamGraph createAndInitializeJobGraph(
895:             org.apache.flink.streaming.api.graph.StreamGraph streamGraph, @Nullable JobID jobId) {
896:         StreamGraph jobGraph = new StreamGraph(jobId, streamGraph.getJobName());
897:         jobGraph.setJobType(streamGraph.getJobType());
898:         jobGraph.setDynamic(streamGraph.isDynamic());
899: 
900:         jobGraph.enableApproximateLocalRecovery(
901:                 streamGraph.getCheckpointConfig().isApproximateLocalRecoveryEnabled());
902: 
903:         jobGraph.setSnapshotSettings(streamGraph.getCheckpointingSettings());
904:         jobGraph.setSavepointRestoreSettings(streamGraph.getSavepointRestoreSettings());
905:         for (Map.Entry<String, DistributedCache.DistributedCacheEntry> entry :
906:                 streamGraph.getUserArtifacts().entrySet()) {
907:             jobGraph.addUserArtifact(entry.getKey(), entry.getValue());
908:         }
909: 
910:         streamGraph.getUserJarBlobKeys().forEach(jobGraph::addUserJarBlobKey);
911:         jobGraph.setClasspaths(streamGraph.getClasspath());
912: 
913:         ExecutionConfig executionConfig = streamGraph.getExecutionConfig();
914:         if (executionConfig == null) {
915:             jobGraph.setSerializedExecutionConfig(streamGraph.getSerializedExecutionConfig());
916:         } else {
917:             try {
918:                 jobGraph.setExecutionConfig(streamGraph.getExecutionConfig());
919:             } catch (IOException e) {
920:                 throw new IllegalConfigurationException(
921:                         "Could not serialize the ExecutionConfig."
922:                                 + "This indicates that non-serializable types (like custom serializers) were registered");
923:             }
924:         }
925: 
926:         jobGraph.setJobConfiguration(streamGraph.getJobConfiguration());
927: 
928:         if (!streamGraph.getJobStatusHooks().isEmpty()) {
929:             jobGraph.setJobStatusHooks(streamGraph.getJobStatusHooks());
930:         }
931: 
932:         return jobGraph;
933:     }
