935:     public static void createSourceChainInfo(
936:             StreamNode sourceNode,
937:             Map<Integer, OperatorChainInfo> chainEntryPoints,
938:             JobVertexBuildContext jobVertexBuildContext) {
939:         Integer sourceNodeId = sourceNode.getId();
940:         StreamEdge sourceOutEdge = sourceNode.getOutEdges().get(0);
941: 
942:         final OperatorChainInfo chainInfo =
943:                 chainEntryPoints.computeIfAbsent(
944:                         sourceOutEdge.getTargetId(),
945:                         (k) -> new OperatorChainInfo(sourceOutEdge.getTargetId()));
946:         final OperatorID opId = new OperatorID(jobVertexBuildContext.getHash(sourceNodeId));
947:         final OperatorInfo operatorInfo = chainInfo.createAndGetOperatorInfo(sourceNodeId, opId);
948:         final StreamConfig.SourceInputConfig inputConfig =
949:                 new StreamConfig.SourceInputConfig(sourceOutEdge);
950:         final StreamConfig operatorConfig = new StreamConfig(new Configuration());
951:         setOperatorConfig(sourceNodeId, operatorConfig, chainInfo, jobVertexBuildContext);
952:         setOperatorChainedOutputsConfig(
953:                 operatorConfig, Collections.emptyList(), jobVertexBuildContext);
954:         // we cache the non-chainable outputs here, and set the non-chained config later
955:         operatorInfo.addNonChainableOutputs(Collections.emptyList());
956: 
957:         operatorConfig.setChainIndex(0); // sources are always first
958:         operatorConfig.setOperatorID(opId);
959:         operatorConfig.setOperatorName(sourceNode.getOperatorName());
960: 
961:         final SourceOperatorFactory<?> sourceOpFact =
962:                 (SourceOperatorFactory<?>)
963:                         Preconditions.checkNotNull(sourceNode.getOperatorFactory());
964:         final OperatorCoordinator.Provider coord =
965:                 sourceOpFact.getCoordinatorProvider(sourceNode.getOperatorName(), opId);
966: 
967:         chainInfo.addChainedSource(sourceNode, new ChainedSourceInfo(operatorConfig, inputConfig));
968:         chainInfo.addCoordinatorProvider(coord);
969:     }
