1000:                 nameWithChainedSourcesInfo(
1001:                         streamGraph.getStreamNode(vertexID).getOperatorName(), chainedSourceInfos);
1002:         if (chainedOutputs.size() > 1) {
1003:             List<String> outputChainedNames = new ArrayList<>();
1004:             for (StreamEdge chainable : chainedOutputs) {
1005:                 outputChainedNames.add(chainedNames.get(chainable.getTargetId()));
