1570:     public static IntermediateDataSet connect(
1571:             Integer headOfChain,
1572:             StreamEdge edge,
1573:             NonChainedOutput output,
1574:             Map<Integer, JobVertex> jobVertices,
1575:             JobVertexBuildContext jobVertexBuildContext) {
1576: 
1577:         jobVertexBuildContext.addPhysicalEdgesInOrder(edge);
1578: 
1579:         Integer downStreamVertexID = edge.getTargetId();
1580: 
1581:         JobVertex headVertex = jobVertices.get(headOfChain);
1582:         JobVertex downStreamVertex = jobVertices.get(downStreamVertexID);
1583: 
1584:         StreamConfig downStreamConfig = new StreamConfig(downStreamVertex.getConfiguration());
1585: 
1586:         downStreamConfig.setNumberOfNetworkInputs(downStreamConfig.getNumberOfNetworkInputs() + 1);
1587: 
1588:         StreamPartitioner<?> partitioner = output.getPartitioner();
1589:         ResultPartitionType resultPartitionType = output.getPartitionType();
1590: 
1591:         checkBufferTimeout(resultPartitionType, edge);
1592: 
1593:         JobEdge jobEdge;
1594:         if (partitioner.isPointwise()) {
1595:             jobEdge =
1596:                     downStreamVertex.connectNewDataSetAsInput(
1597:                             headVertex,
1598:                             DistributionPattern.POINTWISE,
1599:                             resultPartitionType,
1600:                             output.getDataSetId(),
1601:                             partitioner.isBroadcast(),
1602:                             partitioner.getClass().equals(ForwardPartitioner.class));
1603:         } else {
1604:             jobEdge =
1605:                     downStreamVertex.connectNewDataSetAsInput(
1606:                             headVertex,
1607:                             DistributionPattern.ALL_TO_ALL,
1608:                             resultPartitionType,
1609:                             output.getDataSetId(),
1610:                             partitioner.isBroadcast(),
1611:                             partitioner.getClass().equals(ForwardPartitioner.class));
1612:         }
1613: 
1614:         // set strategy name so that web interface can show it.
1615:         jobEdge.setShipStrategyName(partitioner.toString());
1616:         jobEdge.setDownstreamSubtaskStateMapper(partitioner.getDownstreamSubtaskStateMapper());
1617:         jobEdge.setUpstreamSubtaskStateMapper(partitioner.getUpstreamSubtaskStateMapper());
1618: 
1619:         if (LOG.isDebugEnabled()) {
1620:             LOG.debug(
1621:                     "CONNECTED: {} - {} -> {}",
1622:                     partitioner.getClass().getSimpleName(),
1623:                     headOfChain,
1624:                     downStreamVertexID);
1625:         }
1626: 
1627:         return jobEdge.getSource();
1628:     }
