1636:     private static void checkBufferTimeout(ResultPartitionType type, StreamEdge edge) {
1637:         long bufferTimeout = edge.getBufferTimeout();
1638:         if (!type.canBePipelinedConsumed()
1639:                 && bufferTimeout != ExecutionOptions.DISABLED_NETWORK_BUFFER_TIMEOUT) {
1640:             throw new UnsupportedOperationException(
1641:                     "only canBePipelinedConsumed partition support buffer timeout "
1642:                             + bufferTimeout
1643:                             + " for src operator in edge "
