1713:     public static boolean isChainable(
1714:             StreamEdge edge, org.apache.flink.streaming.api.graph.StreamGraph streamGraph, boolean allowChainWithDefaultParallelism) {
1715:         StreamNode downStreamVertex = streamGraph.getTargetVertex(edge);
1716: 
1717:         return downStreamVertex.getInEdges().size() == 1
1718:                 && isChainableInput(edge, streamGraph, allowChainWithDefaultParallelism);
