1721:     public static boolean isChainableSource(StreamNode streamNode, org.apache.flink.streaming.api.graph.StreamGraph streamGraph) {
1722:         if (streamNode.getOperatorFactory() == null
1723:                 || !(streamNode.getOperatorFactory() instanceof SourceOperatorFactory)
1724:                 || streamNode.getOutEdges().size() != 1) {
1725:             return false;
1726:         }
1727:         final StreamEdge sourceOutEdge = streamNode.getOutEdges().get(0);
1728:         final StreamNode target = streamGraph.getStreamNode(sourceOutEdge.getTargetId());
1729:         final ChainingStrategy targetChainingStrategy =
1730:                 Preconditions.checkNotNull(target.getOperatorFactory()).getChainingStrategy();
1731:         return targetChainingStrategy == ChainingStrategy.HEAD_WITH_SOURCES
1732:                 && isChainableInput(sourceOutEdge, streamGraph, false);
1733:     }
1734: 
1735:     private static boolean isChainableInput(
1736:             StreamEdge edge, org.apache.flink.streaming.api.graph.StreamGraph streamGraph, boolean allowChainWithDefaultParallelism) {
1737:         StreamNode upStreamVertex = streamGraph.getSourceVertex(edge);
1738:         StreamNode downStreamVertex = streamGraph.getTargetVertex(edge);
1739: 
1740:         if (!(streamGraph.isChainingEnabled()
1741:                 && upStreamVertex.isSameSlotSharingGroup(downStreamVertex)
1742:                 && areOperatorsChainable(
1743:                         upStreamVertex,
1744:                         downStreamVertex,
1745:                         streamGraph,
1746:                         allowChainWithDefaultParallelism)
1747:                 && arePartitionerAndExchangeModeChainable(
1748:                         edge.getPartitioner(), edge.getExchangeMode(), streamGraph.isDynamic()))) {
1749: 
1750:             return false;
1751:         }
1752: 
1753:         // check that we do not have a union operation, because unions currently only work
1754:         // through the network/byte-channel stack.
1755:         // we check that by testing that each "type" (which means input position) is used only once
1756:         for (StreamEdge inEdge : downStreamVertex.getInEdges()) {
1757:             if (inEdge != edge && inEdge.getTypeNumber() == edge.getTypeNumber()) {
1758:                 return false;
1759:             }
1760:         }
1761:         return true;
1762:     }
