1764:     @VisibleForTesting
1765:     static boolean arePartitionerAndExchangeModeChainable(
1766:             StreamPartitioner<?> partitioner,
1767:             StreamExchangeMode exchangeMode,
1768:             boolean isDynamicGraph) {
1769:         if (partitioner instanceof ForwardForConsecutiveHashPartitioner) {
1770:             checkState(isDynamicGraph);
1771:             return true;
1772:         } else if ((partitioner instanceof ForwardPartitioner)
1773:                 && exchangeMode != StreamExchangeMode.BATCH) {
1774:             return true;
1775:         } else {
1776:             return false;
1777:         }
1778:     }
1779: 
1780:     @VisibleForTesting
1781:     static boolean areOperatorsChainable(
1782:             StreamNode upStreamVertex,
1783:             StreamNode downStreamVertex,
1784:             org.apache.flink.streaming.api.graph.StreamGraph streamGraph,
1785:             boolean allowChainWithDefaultParallelism) {
1786:         StreamOperatorFactory<?> upStreamOperator = upStreamVertex.getOperatorFactory();
1787:         StreamOperatorFactory<?> downStreamOperator = downStreamVertex.getOperatorFactory();
1788:         if (downStreamOperator == null || upStreamOperator == null) {
1789:             return false;
1790:         }
1791: 
1792:         // yielding operators cannot be chained to legacy sources
1793:         // unfortunately the information that vertices have been chained is not preserved at this
1794:         // point
1795:         if (downStreamOperator instanceof YieldingOperatorFactory
1796:                 && getHeadOperator(upStreamVertex, streamGraph).isLegacySource()) {
1797:             return false;
1798:         }
1799: 
1800:         // we use switch/case here to make sure this is exhaustive if ever values are added to the
1801:         // ChainingStrategy enum
1802:         boolean isChainable;
1803: 
1804:         switch (upStreamOperator.getChainingStrategy()) {
1805:             case NEVER:
1806:                 isChainable = false;
1807:                 break;
1808:             case ALWAYS:
1809:             case HEAD:
1810:             case HEAD_WITH_SOURCES:
1811:                 isChainable = true;
1812:                 break;
1813:             default:
1814:                 throw new RuntimeException(
1815:                         "Unknown chaining strategy: " + upStreamOperator.getChainingStrategy());
1816:         }
1817: 
1818:         switch (downStreamOperator.getChainingStrategy()) {
1819:             case NEVER:
1820:             case HEAD:
1821:                 isChainable = false;
1822:                 break;
1823:             case ALWAYS:
1824:                 // keep the value from upstream
1825:                 break;
1826:             case HEAD_WITH_SOURCES:
1827:                 // only if upstream is a source
1828:                 isChainable &= (upStreamOperator instanceof SourceOperatorFactory);
1829:                 break;
1830:             default:
1831:                 throw new RuntimeException(
1832:                         "Unknown chaining strategy: " + downStreamOperator.getChainingStrategy());
1833:         }
1834: 
1835:         // When allowChainWithDefaultParallelism is true, any vertex with default parallelism can
1836:         // be chained, otherwise only vertices with the same parallelism can be chained.
1837:         if (allowChainWithDefaultParallelism) {
1838:             isChainable &=
1839:                     (upStreamVertex.getParallelism() == downStreamVertex.getParallelism()
1840:                             || upStreamVertex.getParallelism()
1841:                                     == ExecutionConfig.PARALLELISM_DEFAULT
1842:                             || downStreamVertex.getParallelism()
1843:                                     == ExecutionConfig.PARALLELISM_DEFAULT);
1844:         } else {
1845:             isChainable &= upStreamVertex.getParallelism() == downStreamVertex.getParallelism();
1846:         }
1847: 
1848:         if (!streamGraph.isChainingOfOperatorsWithDifferentMaxParallelismEnabled()) {
1849:             isChainable &=
1850:                     upStreamVertex.getMaxParallelism() == downStreamVertex.getMaxParallelism();
1851:         }
1852: 
1853:         return isChainable;
1854:     }
