1911:     private static void setSlotSharing(JobVertexBuildContext jobVertexBuildContext) {
1912:         org.apache.flink.streaming.api.graph.StreamGraph streamGraph = jobVertexBuildContext.getStreamGraph();
1913:         final Map<String, SlotSharingGroup> specifiedSlotSharingGroups = new HashMap<>();
1914:         final Map<JobVertexID, SlotSharingGroup> vertexRegionSlotSharingGroups =
1915:                 buildVertexRegionSlotSharingGroups(jobVertexBuildContext);
1916:         final Map<Integer, JobVertex> jobVertices = jobVertexBuildContext.getJobVerticesInOrder();
1917: 
1918:         for (Map.Entry<Integer, JobVertex> entry : jobVertices.entrySet()) {
1919: 
1920:             final JobVertex vertex = entry.getValue();
1921:             final String slotSharingGroupKey =
1922:                     streamGraph.getStreamNode(entry.getKey()).getSlotSharingGroup();
1923: 
1924:             checkNotNull(slotSharingGroupKey, "StreamNode slot sharing group must not be null");
1925: 
1926:             final SlotSharingGroup effectiveSlotSharingGroup;
1927:             if (slotSharingGroupKey.equals(StreamGraphGenerator.DEFAULT_SLOT_SHARING_GROUP)) {
1928:                 // fallback to the region slot sharing group by default
1929:                 effectiveSlotSharingGroup =
1930:                         checkNotNull(vertexRegionSlotSharingGroups.get(vertex.getID()));
1931:             } else {
1932:                 checkState(
1933:                         !jobVertexBuildContext.hasHybridResultPartition(),
1934:                         "hybrid shuffle mode currently does not support setting non-default slot sharing group.");
1935: 
1936:                 effectiveSlotSharingGroup =
1937:                         specifiedSlotSharingGroups.computeIfAbsent(
1938:                                 slotSharingGroupKey,
1939:                                 k -> {
1940:                                     SlotSharingGroup ssg = new SlotSharingGroup();
1941:                                     streamGraph
1942:                                             .getSlotSharingGroupResource(k)
1943:                                             .ifPresent(ssg::setResourceProfile);
1944:                                     return ssg;
1945:                                 });
1946:             }
1947: 
1948:             vertex.setSlotSharingGroup(effectiveSlotSharingGroup);
1949:         }
1950:     }
