1963:     /**
1964:      * Maps a vertex to its region slot sharing group. If {@link
1965:      * org.apache.flink.streaming.api.graph.StreamGraph#isAllVerticesInSameSlotSharingGroupByDefault()} returns true, all regions will be
1966:      * in the same slot sharing group.
1967:      */
1968:     private static Map<JobVertexID, SlotSharingGroup> buildVertexRegionSlotSharingGroups(
1969:             JobVertexBuildContext jobVertexBuildContext) {
1970:         org.apache.flink.streaming.api.graph.StreamGraph streamGraph = jobVertexBuildContext.getStreamGraph();
1971:         final Map<JobVertexID, SlotSharingGroup> vertexRegionSlotSharingGroups = new HashMap<>();
1972:         final SlotSharingGroup defaultSlotSharingGroup =
1973:                 jobVertexBuildContext.getDefaultSlotSharingGroup();
1974:         streamGraph
1975:                 .getSlotSharingGroupResource(StreamGraphGenerator.DEFAULT_SLOT_SHARING_GROUP)
1976:                 .ifPresent(defaultSlotSharingGroup::setResourceProfile);
1977: 
1978:         final boolean allRegionsInSameSlotSharingGroup =
1979:                 streamGraph.isAllVerticesInSameSlotSharingGroupByDefault();
1980: 
1981:         final Iterable<DefaultLogicalPipelinedRegion> regions =
1982:                 DefaultLogicalTopology.fromStreamGraph(jobVertexBuildContext.getJobGraph())
1983:                         .getAllPipelinedRegions();
1984:         for (DefaultLogicalPipelinedRegion region : regions) {
1985:             final SlotSharingGroup regionSlotSharingGroup;
1986:             if (allRegionsInSameSlotSharingGroup) {
1987:                 regionSlotSharingGroup = defaultSlotSharingGroup;
1988:             } else {
1989:                 regionSlotSharingGroup = new SlotSharingGroup();
1990:                 streamGraph
1991:                         .getSlotSharingGroupResource(
1992:                                 StreamGraphGenerator.DEFAULT_SLOT_SHARING_GROUP)
1993:                         .ifPresent(regionSlotSharingGroup::setResourceProfile);
1994:             }
1995: 
1996:             for (LogicalVertex vertex : region.getVertices()) {
1997:                 vertexRegionSlotSharingGroups.put(vertex.getId(), regionSlotSharingGroup);
1998:             }
1999:         }
2000: 
2001:         return vertexRegionSlotSharingGroups;
2002:     }
