399:         Map<Integer, Map<Integer, StreamConfig>> chainedConfigs =
400:                 jobVertexBuildContext.getChainedConfigs();
401:         if (chainedConfigs.containsKey(headOpId)) {
402:             for (StreamEdge edge : node.getOutEdges()) {
403:                 int targetId = edge.getTargetId();
404:                 if (chainedConfigs.get(headOpId).containsKey(targetId)) {
405:                     chainedOutput.add(targetId);
406:                 }
407:             }
408:         }
409:         return chainedOutput;
410:     }
