568:     private Map<Integer, OperatorChainInfo> buildChainedInputsAndGetHeadInputs() {
569:         final Map<Integer, OperatorChainInfo> chainEntryPoints = new HashMap<>();
570: 
571:         for (Integer sourceNodeId : streamGraph.getSourceIDs()) {
572:             final StreamNode sourceNode = streamGraph.getStreamNode(sourceNodeId);
573:             if (isChainableSource(sourceNode, streamGraph)) {
574:                 createSourceChainInfo(sourceNode, chainEntryPoints, jobVertexBuildContext);
