793:     /**
794:      * This method is used to reset or set job vertices' parallelism for dynamic graph:
795:      *
796:      * <p>1. Reset parallelism for job vertices whose parallelism is not configured.
797:      *
798:      * <p>2. Set parallelism and maxParallelism for job vertices in forward group, to ensure the
799:      * parallelism and maxParallelism of vertices in the same forward group to be the same; set the
800:      * parallelism at early stage if possible, to avoid invalid partition reuse.
801:      */
802:     private void setVertexParallelismsForDynamicGraphIfNecessary() {
803:         final Map<Integer, JobVertex> jobVertices = jobVertexBuildContext.getJobVerticesInOrder();
804:         // Note that the jobVertices are reverse topological order
805:         final List<JobVertex> topologicalOrderVertices =
806:                 IterableUtils.toStream(jobVertices.values()).collect(Collectors.toList());
807:         Collections.reverse(topologicalOrderVertices);
808: 
809:         // reset parallelism for job vertices whose parallelism is not configured
810:         jobVertices.forEach(
811:                 (startNodeId, jobVertex) -> {
812:                     final OperatorChainInfo chainInfo =
813:                             jobVertexBuildContext.getChainInfo(startNodeId);
814:                     if (!jobVertex.isParallelismConfigured()
815:                             && streamGraph.isAutoParallelismEnabled()) {
816:                         jobVertex.setParallelism(ExecutionConfig.PARALLELISM_DEFAULT);
817:                         chainInfo
818:                                 .getAllChainedNodes()
819:                                 .forEach(
820:                                         n ->
821:                                                 n.setParallelism(
822:                                                         ExecutionConfig.PARALLELISM_DEFAULT,
823:                                                         false));
824:                     }
825:                 });
826: 
827:         final Map<JobVertex, Set<JobVertex>> forwardProducersByJobVertex = new HashMap<>();
828:         jobVertices.forEach(
829:                 (startNodeId, jobVertex) -> {
830:                     Set<JobVertex> forwardConsumers =
831:                             jobVertexBuildContext
832:                                     .getChainInfo(startNodeId)
833:                                     .getTransitiveOutEdges()
834:                                     .stream()
835:                                     .filter(
836:                                             edge ->
837:                                                     edge.getPartitioner()
838:                                                             instanceof ForwardPartitioner)
839:                                     .map(StreamEdge::getTargetId)
840:                                     .map(jobVertices::get)
841:                                     .collect(Collectors.toSet());
842: 
843:                     for (JobVertex forwardConsumer : forwardConsumers) {
844:                         forwardProducersByJobVertex.compute(
845:                                 forwardConsumer,
846:                                 (ignored, producers) -> {
847:                                     if (producers == null) {
848:                                         producers = new HashSet<>();
849:                                     }
850:                                     producers.add(jobVertex);
851:                                     return producers;
852:                                 });
853:                     }
854:                 });
855: 
856:         // compute forward groups
857:         final Map<JobVertexID, JobVertexForwardGroup> forwardGroupsByJobVertexId =
858:                 ForwardGroupComputeUtil.computeForwardGroups(
859:                         topologicalOrderVertices,
860:                         jobVertex ->
861:                                 forwardProducersByJobVertex.getOrDefault(
862:                                         jobVertex, Collections.emptySet()));
863: 
864:         jobVertices.forEach(
865:                 (startNodeId, jobVertex) -> {
866:                     ForwardGroup forwardGroup = forwardGroupsByJobVertexId.get(jobVertex.getID());
867:                     // set parallelism for vertices in forward group
868:                     if (forwardGroup != null && forwardGroup.isParallelismDecided()) {
869:                         jobVertex.setParallelism(forwardGroup.getParallelism());
870:                         jobVertex.setParallelismConfigured(true);
871:                         jobVertexBuildContext
872:                                 .getChainInfo(startNodeId)
873:                                 .getAllChainedNodes()
874:                                 .forEach(
875:                                         streamNode ->
876:                                                 streamNode.setParallelism(
877:                                                         forwardGroup.getParallelism(), true));
878:                     }
879: 
880:                     // set max parallelism for vertices in forward group
881:                     if (forwardGroup != null && forwardGroup.isMaxParallelismDecided()) {
882:                         jobVertex.setMaxParallelism(forwardGroup.getMaxParallelism());
883:                         jobVertexBuildContext
884:                                 .getChainInfo(startNodeId)
885:                                 .getAllChainedNodes()
886:                                 .forEach(
887:                                         streamNode ->
888:                                                 streamNode.setMaxParallelism(
889:                                                         forwardGroup.getMaxParallelism()));
890:                     }
891:                 });
892:     }
