985:     public static String createChainedName(
986:             Integer vertexID,
987:             List<StreamEdge> chainedOutputs,
988:             Optional<OperatorChainInfo> operatorChainInfo,
989:             Map<Integer, String> chainedNames,
990:             JobVertexBuildContext jobVertexBuildContext) {
991:         org.apache.flink.streaming.api.graph.StreamGraph streamGraph = jobVertexBuildContext.getStreamGraph();
992:         List<ChainedSourceInfo> chainedSourceInfos =
993:                 operatorChainInfo
994:                         .map(
995:                                 chainInfo ->
996:                                         getChainedSourcesByVertexId(
997:                                                 vertexID, chainInfo, streamGraph))
998:                         .orElse(Collections.emptyList());
999:         final String operatorName =
1000:                 nameWithChainedSourcesInfo(
1001:                         streamGraph.getStreamNode(vertexID).getOperatorName(), chainedSourceInfos);
