1057:     public static JobVertex createJobVertex(
1058:             OperatorChainInfo chainInfo,
1059:             Executor serializationExecutor,
1060:             JobVertexBuildContext jobVertexBuildContext) {
1061: 
1062:         Integer streamNodeId = chainInfo.getStartNodeId();
1063: 
1064:         JobVertex jobVertex;
1065:         StreamNode streamNode = jobVertexBuildContext.getStreamGraph().getStreamNode(streamNodeId);
1066: 
1067:         byte[] hash = jobVertexBuildContext.getHash(streamNodeId);
1068: 
1069:         if (hash == null) {
1070:             throw new IllegalStateException(
1071:                     "Cannot find node hash. "
1072:                             + "Did you generate them before calling this method?");
1073:         }
1074: 
1075:         JobVertexID jobVertexId = new JobVertexID(hash);
1076: 
1077:         List<ChainedOperatorHashInfo> chainedOperators =
1078:                 chainInfo.getChainedOperatorHashes(streamNodeId);
1079:         List<OperatorIDPair> operatorIDPairs = new ArrayList<>();
1080:         if (chainedOperators != null) {
1081:             for (ChainedOperatorHashInfo chainedOperator : chainedOperators) {
1082:                 OperatorID userDefinedOperatorID =
1083:                         chainedOperator.getUserDefinedOperatorId() == null
1084:                                 ? null
1085:                                 : new OperatorID(chainedOperator.getUserDefinedOperatorId());
1086:                 operatorIDPairs.add(
1087:                         OperatorIDPair.of(
1088:                                 new OperatorID(chainedOperator.getGeneratedOperatorId()),
1089:                                 userDefinedOperatorID,
1090:                                 chainedOperator.getStreamNode().getOperatorName(),
1091:                                 chainedOperator.getStreamNode().getTransformationUID()));
1092:             }
1093:         }
1094: 
1095:         if (chainInfo.hasFormatContainer()) {
1096:             jobVertex =
1097:                     new InputOutputFormatVertex(
1098:                             chainInfo.getChainedName(streamNodeId), jobVertexId, operatorIDPairs);
1099:             chainInfo
1100:                     .getOrCreateFormatContainer()
1101:                     .write(new TaskConfig(jobVertex.getConfiguration()));
1102:         } else {
1103:             jobVertex =
1104:                     new JobVertex(
1105:                             chainInfo.getChainedName(streamNodeId), jobVertexId, operatorIDPairs);
1106:         }
1107: 
1108:         if (streamNode.getConsumeClusterDatasetId() != null) {
1109:             jobVertex.addIntermediateDataSetIdToConsume(streamNode.getConsumeClusterDatasetId());
1110:         }
1111: 
1112:         final List<CompletableFuture<SerializedValue<OperatorCoordinator.Provider>>>
1113:                 serializationFutures = new ArrayList<>();
1114:         for (OperatorCoordinator.Provider coordinatorProvider :
1115:                 chainInfo.getCoordinatorProviders()) {
1116:             serializationFutures.add(
1117:                     CompletableFuture.supplyAsync(
1118:                             () -> {
1119:                                 try {
1120:                                     return new SerializedValue<>(coordinatorProvider);
1121:                                 } catch (IOException e) {
1122:                                     throw new FlinkRuntimeException(
1123:                                             String.format(
1124:                                                     "Coordinator Provider for node %s is not serializable.",
1125:                                                     chainInfo.getChainedName(streamNodeId)),
1126:                                             e);
1127:                                 }
1128:                             },
1129:                             serializationExecutor));
1130:         }
1131:         if (!serializationFutures.isEmpty()) {
1132:             jobVertexBuildContext.putCoordinatorSerializationFutures(
1133:                     jobVertexId, serializationFutures);
1134:         }
1135: 
1136:         jobVertex.setResources(
1137:                 chainInfo.getChainedMinResources(streamNodeId),
1138:                 chainInfo.getChainedPreferredResources(streamNodeId));
1139: 
1140:         jobVertex.setInvokableClass(streamNode.getJobVertexClass());
1141: 
1142:         int parallelism = streamNode.getParallelism();
1143: 
1144:         if (parallelism > 0) {
1145:             jobVertex.setParallelism(parallelism);
1146:         } else {
1147:             parallelism = jobVertex.getParallelism();
1148:         }
1149: 
1150:         jobVertex.setMaxParallelism(streamNode.getMaxParallelism());
1151: 
1152:         if (LOG.isDebugEnabled()) {
1153:             LOG.debug("Parallelism set: {} for {}", parallelism, streamNodeId);
1154:         }
1155: 
1156:         jobVertexBuildContext.addJobVertex(streamNodeId, jobVertex);
1157:         jobVertexBuildContext.getJobGraph().addVertex(jobVertex);
1158: 
1159:         jobVertex.setParallelismConfigured(
1160:                 chainInfo.getAllChainedNodes().stream()
1161:                         .anyMatch(StreamNode::isParallelismConfigured));
1162: 
1163:         return jobVertex;
1164:     }
