1166:     public static void setOperatorConfig(
1167:             Integer vertexId,
1168:             StreamConfig config,
1169:             OperatorChainInfo chainInfo,
1170:             JobVertexBuildContext jobVertexBuildContext) {
1171:         org.apache.flink.streaming.api.graph.StreamGraph streamGraph = jobVertexBuildContext.getStreamGraph();
1172:         OperatorInfo operatorInfo = chainInfo.getOperatorInfo(vertexId);
1173:         Map<Integer, ChainedSourceInfo> chainedSources = chainInfo.getChainedSources();
1174:         StreamNode vertex = streamGraph.getStreamNode(vertexId);
1175: 
1176:         config.setVertexID(vertexId);
1177: 
1178:         // build the inputs as a combination of source and network inputs
1179:         final List<StreamEdge> inEdges = vertex.getInEdges();
1180:         final TypeSerializer<?>[] inputSerializers = vertex.getTypeSerializersIn();
1181: 
1182:         final StreamConfig.InputConfig[] inputConfigs =
1183:                 new StreamConfig.InputConfig[inputSerializers.length];
1184: 
1185:         int inputGateCount = 0;
1186:         for (final StreamEdge inEdge : inEdges) {
1187:             final ChainedSourceInfo chainedSource = chainedSources.get(inEdge.getSourceId());
1188: 
1189:             final int inputIndex =
1190:                     inEdge.getTypeNumber() == 0
1191:                             ? 0 // single input operator
1192:                             : inEdge.getTypeNumber() - 1; // in case of 2 or more inputs
1193: 
1194:             if (chainedSource != null) {
1195:                 // chained source is the input
1196:                 if (inputConfigs[inputIndex] != null) {
1197:                     throw new IllegalStateException(
1198:                             "Trying to union a chained source with another input.");
1199:                 }
1200:                 inputConfigs[inputIndex] = chainedSource.getInputConfig();
1201:                 jobVertexBuildContext
1202:                         .getOrCreateChainedConfig(vertexId)
1203:                         .put(inEdge.getSourceId(), chainedSource.getOperatorConfig());
1204:             } else {
1205:                 // network input. null if we move to a new input, non-null if this is a further edge
1206:                 // that is union-ed into the same input
1207:                 if (inputConfigs[inputIndex] == null) {
1208:                     // PASS_THROUGH is a sensible default for streaming jobs. Only for BATCH
1209:                     // execution can we have sorted inputs
1210:                     StreamConfig.InputRequirement inputRequirement =
1211:                             vertex.getInputRequirements()
1212:                                     .getOrDefault(
1213:                                             inputIndex, StreamConfig.InputRequirement.PASS_THROUGH);
1214:                     inputConfigs[inputIndex] =
1215:                             new StreamConfig.NetworkInputConfig(
1216:                                     inputSerializers[inputIndex],
1217:                                     inputGateCount++,
1218:                                     inputRequirement);
1219:                 }
1220:             }
1221:         }
1222: 
1223:         // set the input config of the vertex if it consumes from cached intermediate dataset.
1224:         if (vertex.getConsumeClusterDatasetId() != null) {
1225:             config.setNumberOfNetworkInputs(1);
1226:             inputConfigs[0] = new StreamConfig.NetworkInputConfig(inputSerializers[0], 0);
1227:         }
1228: 
1229:         config.setInputs(inputConfigs);
1230: 
1231:         config.setTypeSerializerOut(vertex.getTypeSerializerOut());
1232: 
1233:         config.setStreamOperatorFactory(vertex.getOperatorFactory());
1234: 
1235:         final CheckpointConfig checkpointCfg = streamGraph.getCheckpointConfig();
1236: 
1237:         config.setSerializedStateBackend(
1238:                 streamGraph.getCheckpointingSettings().getDefaultStateBackend(),
1239:                 Boolean.TRUE.equals(
1240:                         streamGraph
1241:                                 .getCheckpointingSettings()
1242:                                 .isStateBackendUseManagedMemory()
1243:                                 .getAsBoolean()));
1244:         config.setSerializedCheckpointStorage(
1245:                 streamGraph.getCheckpointingSettings().getDefaultCheckpointStorage());
1246:         config.setGraphContainingLoops(streamGraph.isIterative());
1247:         config.setTimerServiceProvider(streamGraph.getTimerServiceProvider());
1248:         config.setCheckpointingEnabled(checkpointCfg.isCheckpointingEnabled());
1249:         config.getConfiguration()
1250:                 .set(
1251:                         CheckpointingOptions.ENABLE_CHECKPOINTS_AFTER_TASKS_FINISH,
1252:                         streamGraph.isEnableCheckpointsAfterTasksFinish());
1253:         config.setCheckpointMode(org.apache.flink.streaming.api.graph.StreamGraph.getCheckpointingMode(checkpointCfg));
1254:         config.setUnalignedCheckpointsEnabled(checkpointCfg.isUnalignedCheckpointsEnabled());
1255:         config.setUnalignedCheckpointsSplittableTimersEnabled(
1256:                 checkpointCfg.isUnalignedCheckpointsInterruptibleTimersEnabled());
1257:         config.setAlignedCheckpointTimeout(checkpointCfg.getAlignedCheckpointTimeout());
1258:         config.setMaxSubtasksPerChannelStateFile(checkpointCfg.getMaxSubtasksPerChannelStateFile());
1259:         config.setMaxConcurrentCheckpoints(checkpointCfg.getMaxConcurrentCheckpoints());
1260: 
1261:         for (int i = 0; i < vertex.getStatePartitioners().length; i++) {
1262:             config.setStatePartitioner(i, vertex.getStatePartitioners()[i]);
1263:         }
1264:         config.setStateKeySerializer(vertex.getStateKeySerializer());
1265: 
1266:         Class<? extends TaskInvokable> vertexClass = vertex.getJobVertexClass();
1267: 
1268:         if (vertexClass.equals(StreamIterationHead.class)
1269:                 || vertexClass.equals(StreamIterationTail.class)) {
1270:             config.setIterationId(streamGraph.getBrokerID(vertexId));
1271:             config.setIterationWaitTime(streamGraph.getLoopTimeout(vertexId));
1272:         }
1273: 
1274:         operatorInfo.setVertexConfig(config);
1275:     }
