1413:     private static List<NonChainedOutput> mayReuseNonChainedOutputs(
1414:             JobVertexID jobVertexId,
1415:             int streamNodeId,
1416:             List<StreamEdge> consumerEdges,
1417:             Map<StreamEdge, NonChainedOutput> outputsConsumedByEdge,
1418:             JobVertexBuildContext jobVertexBuildContext) {
1419:         if (consumerEdges.isEmpty()) {
1420:             return new ArrayList<>();
1421:         }
1422:         List<NonChainedOutput> outputs = new ArrayList<>(consumerEdges.size());
1423:         for (StreamEdge consumerEdge : consumerEdges) {
1424:             checkState(
1425:                     streamNodeId == consumerEdge.getSourceId(), "stream node id must be the same.");
1426:             ResultPartitionType partitionType =
1427:                     getResultPartitionType(consumerEdge, jobVertexBuildContext);
1428:             IntermediateDataSetID dataSetId =
1429:                     new IntermediateDataSetID(jobVertexId, consumerEdge.getEdgeId().hashCode());
1430: 
1431:             boolean isPersistentDataSet =
1432:                     isPersistentIntermediateDataset(partitionType, consumerEdge);
1433:             if (isPersistentDataSet) {
1434:                 partitionType = ResultPartitionType.BLOCKING_PERSISTENT;
1435:                 dataSetId = consumerEdge.getIntermediateDatasetIdToProduce();
1436:             }
1437: 
1438:             if (partitionType.isHybridResultPartition()) {
1439:                 jobVertexBuildContext.setHasHybridResultPartition(true);
1440:                 if (consumerEdge.getPartitioner().isBroadcast()
1441:                         && partitionType == ResultPartitionType.HYBRID_SELECTIVE) {
1442:                     // for broadcast result partition, it can be optimized to always use full
1443:                     // spilling strategy to significantly reduce shuffle data writing cost.
1444:                     LOG.info(
1445:                             "{} result partition has been replaced by {} result partition to support "
1446:                                     + "broadcast optimization, which will reduce shuffle data writing cost.",
1447:                             partitionType.name(),
1448:                             ResultPartitionType.HYBRID_FULL.name());
1449:                     partitionType = ResultPartitionType.HYBRID_FULL;
1450:                 }
1451:             }
1452: 
1453:             createOrReuseOutput(
1454:                     outputs,
1455:                     outputsConsumedByEdge,
1456:                     consumerEdge,
1457:                     isPersistentDataSet,
1458:                     dataSetId,
1459:                     partitionType,
1460:                     jobVertexBuildContext.getStreamGraph());
1461:         }
1462:         return outputs;
1463:     }
1464: 
1465:     private static void createOrReuseOutput(
1466:             List<NonChainedOutput> outputs,
1467:             Map<StreamEdge, NonChainedOutput> outputsConsumedByEdge,
1468:             StreamEdge consumerEdge,
1469:             boolean isPersistentDataSet,
1470:             IntermediateDataSetID dataSetId,
1471:             ResultPartitionType partitionType,
1472:             org.apache.flink.streaming.api.graph.StreamGraph streamGraph) {
1473:         int consumerParallelism =
1474:                 streamGraph.getStreamNode(consumerEdge.getTargetId()).getParallelism();
1475:         int consumerMaxParallelism =
1476:                 streamGraph.getStreamNode(consumerEdge.getTargetId()).getMaxParallelism();
1477:         NonChainedOutput reusableOutput = null;
1478:         if (isPartitionTypeCanBeReuse(partitionType)) {
1479:             for (NonChainedOutput outputCandidate : outputsConsumedByEdge.values()) {
1480:                 // Reusing the same output can improve performance. The target output can be reused
1481:                 // if meeting the following conditions:
1482:                 // 1. all is hybrid partition or are same re-consumable partition.
1483:                 // 2. have the same partitioner, consumer parallelism, persistentDataSetId,
1484:                 // outputTag.
1485:                 if (allHybridOrSameReconsumablePartitionType(
1486:                                 outputCandidate.getPartitionType(), partitionType)
1487:                         && consumerParallelism == outputCandidate.getConsumerParallelism()
1488:                         && consumerMaxParallelism == outputCandidate.getConsumerMaxParallelism()
1489:                         && Objects.equals(
1490:                                 outputCandidate.getPersistentDataSetId(),
1491:                                 consumerEdge.getIntermediateDatasetIdToProduce())
1492:                         && Objects.equals(
1493:                                 outputCandidate.getOutputTag(), consumerEdge.getOutputTag())
1494:                         && Objects.equals(
1495:                                 consumerEdge.getPartitioner(), outputCandidate.getPartitioner())) {
1496:                     reusableOutput = outputCandidate;
1497:                     outputsConsumedByEdge.put(consumerEdge, reusableOutput);
1498:                     checkAndReplaceReusableHybridPartitionType(reusableOutput);
1499:                     break;
1500:                 }
1501:             }
1502:         }
1503:         if (reusableOutput == null) {
1504:             NonChainedOutput output =
1505:                     new NonChainedOutput(
1506:                             consumerEdge.supportsUnalignedCheckpoints(),
1507:                             consumerEdge.getSourceId(),
1508:                             consumerParallelism,
1509:                             consumerMaxParallelism,
1510:                             consumerEdge.getBufferTimeout(),
1511:                             isPersistentDataSet,
1512:                             dataSetId,
1513:                             consumerEdge.getOutputTag(),
1514:                             consumerEdge.getPartitioner(),
1515:                             partitionType);
1516:             outputs.add(output);
1517:             outputsConsumedByEdge.put(consumerEdge, output);
1518:         }
1519:     }
1520: 
1521:     private static boolean isPartitionTypeCanBeReuse(ResultPartitionType partitionType) {
1522:         // for non-hybrid partition, partition reuse only works when its re-consumable.
1523:         // for hybrid selective partition, it still has the opportunity to be converted to
1524:         // hybrid full partition to support partition reuse.
1525:         return partitionType.isReconsumable() || partitionType.isHybridResultPartition();
1526:     }
1527: 
1528:     private static boolean allHybridOrSameReconsumablePartitionType(
1529:             ResultPartitionType partitionType1, ResultPartitionType partitionType2) {
1530:         return (partitionType1.isReconsumable() && partitionType1 == partitionType2)
1531:                 || (partitionType1.isHybridResultPartition()
1532:                         && partitionType2.isHybridResultPartition());
1533:     }
