1649:     private static ResultPartitionType getResultPartitionType(
1650:             StreamEdge edge, JobVertexBuildContext jobVertexBuildContext) {
1651:         switch (edge.getExchangeMode()) {
1652:             case PIPELINED:
1653:                 return ResultPartitionType.PIPELINED_BOUNDED;
1654:             case BATCH:
1655:                 return ResultPartitionType.BLOCKING;
1656:             case HYBRID_FULL:
1657:                 return ResultPartitionType.HYBRID_FULL;
1658:             case HYBRID_SELECTIVE:
1659:                 return ResultPartitionType.HYBRID_SELECTIVE;
1660:             case UNDEFINED:
1661:                 return determineUndefinedResultPartitionType(edge, jobVertexBuildContext);
1662:             default:
1663:                 throw new UnsupportedOperationException(
1664:                         "Data exchange mode " + edge.getExchangeMode() + " is not supported yet.");
1665:         }
1666:     }
