1668:     public static ResultPartitionType determineUndefinedResultPartitionType(
1669:             StreamEdge edge, JobVertexBuildContext jobVertexBuildContext) {
1670:         org.apache.flink.streaming.api.graph.StreamGraph streamGraph = jobVertexBuildContext.getStreamGraph();
1671:         Attribute sourceNodeAttribute =
1672:                 streamGraph.getStreamNode(edge.getSourceId()).getAttribute();
1673:         if (sourceNodeAttribute.isNoOutputUntilEndOfInput()) {
1674:             edge.setBufferTimeout(ExecutionOptions.DISABLED_NETWORK_BUFFER_TIMEOUT);
1675:             return ResultPartitionType.BLOCKING;
1676:         }
1677: 
1678:         StreamPartitioner<?> partitioner = edge.getPartitioner();
1679:         switch (streamGraph.getGlobalStreamExchangeMode()) {
1680:             case ALL_EDGES_BLOCKING:
1681:                 return ResultPartitionType.BLOCKING;
1682:             case FORWARD_EDGES_PIPELINED:
1683:                 if (partitioner instanceof ForwardPartitioner) {
1684:                     return ResultPartitionType.PIPELINED_BOUNDED;
1685:                 } else {
1686:                     return ResultPartitionType.BLOCKING;
1687:                 }
1688:             case POINTWISE_EDGES_PIPELINED:
1689:                 if (partitioner.isPointwise()) {
1690:                     return ResultPartitionType.PIPELINED_BOUNDED;
1691:                 } else {
1692:                     return ResultPartitionType.BLOCKING;
1693:                 }
1694:             case ALL_EDGES_PIPELINED:
1695:                 return ResultPartitionType.PIPELINED_BOUNDED;
1696:             case ALL_EDGES_PIPELINED_APPROXIMATE:
1697:                 return ResultPartitionType.PIPELINED_APPROXIMATE;
1698:             case ALL_EDGES_HYBRID_FULL:
1699:                 return ResultPartitionType.HYBRID_FULL;
1700:             case ALL_EDGES_HYBRID_SELECTIVE:
1701:                 return ResultPartitionType.HYBRID_SELECTIVE;
1702:             default:
1703:                 throw new RuntimeException(
1704:                         "Unrecognized global data exchange mode "
1705:                                 + streamGraph.getGlobalStreamExchangeMode());
1706:         }
1707:     }
