1856:     /** Backtraces the head of an operator chain. */
1857:     private static StreamOperatorFactory<?> getHeadOperator(
1858:             StreamNode upStreamVertex, org.apache.flink.streaming.api.graph.StreamGraph streamGraph) {
1859:         if (streamGraph.getHeadOperatorForNodeFromCache(upStreamVertex) == null) {
1860:             if (upStreamVertex.getInEdges().size() == 1
1861:                     && isChainable(upStreamVertex.getInEdges().get(0), streamGraph)) {
1862:                 StreamOperatorFactory<?> headOperator =
1863:                         getHeadOperator(
1864:                                 streamGraph.getSourceVertex(upStreamVertex.getInEdges().get(0)),
1865:                                 streamGraph);
1866:                 streamGraph.cacheHeadOperatorForNode(upStreamVertex, headOperator);
1867:             } else {
1868:                 Preconditions.checkNotNull(upStreamVertex.getOperatorFactory());
1869:                 streamGraph.cacheHeadOperatorForNode(
1870:                         upStreamVertex, upStreamVertex.getOperatorFactory());
1871:             }
1872:         }
1873: 
1874:         return streamGraph.getHeadOperatorForNodeFromCache(upStreamVertex);
1875:     }
