1877:     public static void markSupportingConcurrentExecutionAttempts(
1878:             JobVertexBuildContext jobVertexBuildContext) {
1879:         final Map<Integer, JobVertex> jobVertices = jobVertexBuildContext.getJobVerticesInOrder();
1880:         org.apache.flink.streaming.api.graph.StreamGraph streamGraph = jobVertexBuildContext.getStreamGraph();
1881: 
1882:         for (Map.Entry<Integer, JobVertex> entry : jobVertices.entrySet()) {
1883:             final JobVertex jobVertex = entry.getValue();
1884:             final Set<Integer> vertexOperators = new HashSet<>();
1885:             vertexOperators.add(entry.getKey());
1886:             final Map<Integer, StreamConfig> vertexChainedConfigs =
1887:                     jobVertexBuildContext.getChainedConfigs().get(entry.getKey());
1888:             if (vertexChainedConfigs != null) {
1889:                 vertexOperators.addAll(vertexChainedConfigs.keySet());
1890:             }
1891: 
1892:             // disable supportConcurrentExecutionAttempts of job vertex if there is any stream node
1893:             // does not support it
1894:             boolean supportConcurrentExecutionAttempts = true;
1895:             for (int nodeId : vertexOperators) {
1896:                 final StreamNode streamNode = streamGraph.getStreamNode(nodeId);
1897:                 if (!streamNode.isSupportsConcurrentExecutionAttempts()) {
1898:                     supportConcurrentExecutionAttempts = false;
1899:                     break;
1900:                 }
1901:             }
1902:             jobVertex.setSupportsConcurrentExecutionAttempts(supportConcurrentExecutionAttempts);
1903:         }
1904:     }
