2004:     private static void setCoLocation(JobVertexBuildContext jobVertexBuildContext) {
2005:         final Map<String, Tuple2<SlotSharingGroup, CoLocationGroupImpl>> coLocationGroups =
2006:                 new HashMap<>();
2007:         final Map<Integer, JobVertex> jobVertices = jobVertexBuildContext.getJobVerticesInOrder();
2008:         final org.apache.flink.streaming.api.graph.StreamGraph streamGraph = jobVertexBuildContext.getStreamGraph();
2009: 
2010:         for (Map.Entry<Integer, JobVertex> entry : jobVertices.entrySet()) {
2011: 
2012:             final StreamNode node = streamGraph.getStreamNode(entry.getKey());
2013:             final JobVertex vertex = entry.getValue();
2014:             final SlotSharingGroup sharingGroup = vertex.getSlotSharingGroup();
2015: 
2016:             // configure co-location constraint
2017:             final String coLocationGroupKey = node.getCoLocationGroup();
2018:             if (coLocationGroupKey != null) {
2019:                 if (sharingGroup == null) {
2020:                     throw new IllegalStateException(
2021:                             "Cannot use a co-location constraint without a slot sharing group");
2022:                 }
2023: 
2024:                 Tuple2<SlotSharingGroup, CoLocationGroupImpl> constraint =
2025:                         coLocationGroups.computeIfAbsent(
2026:                                 coLocationGroupKey,
2027:                                 k -> new Tuple2<>(sharingGroup, new CoLocationGroupImpl()));
2028: 
2029:                 if (constraint.f0 != sharingGroup) {
2030:                     throw new IllegalStateException(
2031:                             "Cannot co-locate operators from different slot sharing groups");
2032:                 }
2033: 
2034:                 vertex.updateCoLocationGroup(constraint.f1);
2035:                 constraint.f1.addVertex(vertex);
2036:             }
2037:         }
2038:     }
