2040:     public static void setManagedMemoryFraction(JobVertexBuildContext jobVertexBuildContext) {
2041: 
2042:         final Map<Integer, JobVertex> jobVertices = jobVertexBuildContext.getJobVerticesInOrder();
2043: 
2044:         // all slot sharing groups in this job
2045:         final Set<SlotSharingGroup> slotSharingGroups =
2046:                 Collections.newSetFromMap(new IdentityHashMap<>());
2047: 
2048:         // maps a job vertex ID to its head operator ID
2049:         final Map<JobVertexID, Integer> vertexHeadOperators = new HashMap<>();
2050: 
2051:         // maps a job vertex ID to IDs of all operators in the vertex
2052:         final Map<JobVertexID, Set<Integer>> vertexOperators = new HashMap<>();
2053: 
2054:         for (Map.Entry<Integer, JobVertex> entry : jobVertices.entrySet()) {
2055:             final int headOperatorId = entry.getKey();
2056:             final JobVertex jobVertex = entry.getValue();
2057: 
2058:             final SlotSharingGroup jobVertexSlotSharingGroup = jobVertex.getSlotSharingGroup();
2059: 
2060:             checkState(
2061:                     jobVertexSlotSharingGroup != null,
2062:                     "JobVertex slot sharing group must not be null");
2063:             slotSharingGroups.add(jobVertexSlotSharingGroup);
2064: 
2065:             vertexHeadOperators.put(jobVertex.getID(), headOperatorId);
2066: 
2067:             final Set<Integer> operatorIds = new HashSet<>();
2068:             operatorIds.add(headOperatorId);
2069:             operatorIds.addAll(
2070:                     jobVertexBuildContext
2071:                             .getChainedConfigs()
2072:                             .getOrDefault(headOperatorId, Collections.emptyMap())
2073:                             .keySet());
2074:             vertexOperators.put(jobVertex.getID(), operatorIds);
2075:         }
2076: 
2077:         for (SlotSharingGroup slotSharingGroup : slotSharingGroups) {
2078:             setManagedMemoryFractionForSlotSharingGroup(
2079:                     slotSharingGroup, vertexHeadOperators, vertexOperators, jobVertexBuildContext);
2080:         }
2081:     }
