229:         public IntegerStreamSource(int numRecords, boolean block, boolean needFailover) {
230:             this.numRecords = numRecords;
231:             this.running = true;
232:             this.block = block;
233:             this.needFailover = needFailover;
234:             this.emittedCount = 0;
235:         }
236: 
237:         @Override
238:         public void run(SourceContext<Integer> ctx) throws Exception {
239:             while (running && emittedCount < numRecords) {
240:                 synchronized (ctx.getCheckpointLock()) {
241:                     ctx.collect(emittedCount);
242:                 }
243:                 ++emittedCount;
244:             }
245:             if (block && latch != null) {
246:                 latch.await();
247:             }
248:             if (needFailover && !failedBefore) {
249:                 failedBefore = true;
250:                 throw new RuntimeException("forced failure");
