151:      * this time a full-strategy failover happens.
152:      */
153:     @Test
154:     public void testFailoverAfterSomeTasksFinished() throws Exception {
155:         final Configuration config = new Configuration();
156:         config.set(JobManagerOptions.EXECUTION_FAILOVER_STRATEGY, "full");
157: 
158:         final MiniClusterConfiguration cfg =
159:                 new MiniClusterConfiguration.Builder()
160:                         .withRandomPorts()
161:                         .setNumTaskManagers(1)
162:                         .setNumSlotsPerTaskManager(4)
163:                         .setConfiguration(config)
164:                         .build();
165:         try (MiniCluster miniCluster = new MiniCluster(cfg)) {
166:             miniCluster.start();
167: 
168:             env.enableCheckpointing(100);
169:             StreamGraph jobGraph = getStreamGraph(env, true, true).getJobGraph();
170:             miniCluster.submitJob(jobGraph).get();
