172:             CommonTestUtils.waitForSubtasksToFinish(
173:                     miniCluster,
174:                     jobGraph.getJobID(),
175:                     findVertexByName(jobGraph, "passA -> Sink: sinkA").getID(),
176:                     true);
177:             bigResult.get().clear();
178:             IntegerStreamSource.latch.countDown();
179: 
180:             miniCluster.requestJobResult(jobGraph.getJobID()).get();
181: 
182:             // We are expecting the source to be finished and then restart during failover, so the
183:             // sink should receive records as much as double SMALL_SOURCE_NUM_RECORDS.
184:             // However, in a few cases, a checkpoint happens to be triggered before failover, and
