260:     private static class PassThroughOperator extends AbstractStreamOperator<Integer>
261:             implements OneInputStreamOperator<Integer, Integer> {
262: 
263:         private long checkpointID;
264: 
265:         @Override
266:         public void snapshotState(StateSnapshotContext context) throws Exception {
267:             super.snapshotState(context);
268:             checkpointID = context.getCheckpointId();
269:         }
270: 
271:         @Override
272:         public void processElement(StreamRecord<Integer> element) throws Exception {
273:             output.collect(element);
274:         }
275: 
276:         @Override
277:         public void close() throws Exception {
278:             super.close();
279:             assertThat(checkpointID).isGreaterThan(0);
280:         }
281:     }
