283:     private static class CollectSink extends RichSinkFunction<Integer> {
284:         private final SharedReference<List<Integer>> result;
285: 
286:         public CollectSink(SharedReference<List<Integer>> result) {
287:             this.result = result;
288:         }
289: 
290:         @Override
291:         public void open(OpenContext openContext) throws Exception {
292:             super.open(openContext);
293:         }
294: 
295:         @Override
296:         public void invoke(Integer value, Context context) throws Exception {
297:             result.get().add(value);
298:         }
299:     }
